3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"crypto/md5" //nolint:gosec // matches Cursor's directory naming convention, not security
8		"database/sql"
9		"encoding/base64"
10		"encoding/hex"
11		"encoding/json"
12		"errors"
13		"fmt"
14		"os"
15		"path/filepath"
16	)
