18	// WorkspaceHash returns the Cursor workspace hash for a project path.
19	// Cursor stores per-project chat DBs under MD5(absolute_project_path).
20	func WorkspaceHash(projectPath string) string {
21		sum := md5.Sum([]byte(projectPath)) //nolint:gosec // matches Cursor's convention
22		return hex.EncodeToString(sum[:])
23	}
24	
25	// WorkspaceSlug returns the Cursor project slug for a project path.
26	// Cursor stores per-project transcript JSONLs under a slug derived by stripping
27	// the leading slash and replacing every non-alphanumeric character with a dash
28	// (e.g. dots and underscores too — not just slashes). Delegates to the same
29	// helper cursor's own session-dir resolver uses, so write paths stay aligned
30	// with cursor's read paths even when the workspace path contains "." or "_".
31	func WorkspaceSlug(projectPath string) string {
32		return sanitizePathForCursor(projectPath)
33	}
34	
35	// RestoreCheckpointFiles rebuilds cursor's store.db for this session from the
36	// checkpoint's agent-contributed extras. Supports two archive shapes:
37	//
38	//   - v3 (current): cursor-chat.jsonl — JSONL dump of meta + blobs tables.
39	//     Restore replays the rows into a fresh SQLite file.
40	//   - v2 (legacy, still present on already-pushed checkpoints):
41	//     <sessionID>.cursor-chat.json — opaque base64 of store.db + WAL + SHM.
42	//
43	// The workspace hash is computed from the current working directory,
44	// matching Cursor's own MD5(project_path) convention — run rewind/resume
45	// from the repo that originally hosted the session.
46	func (c *CursorAgent) RestoreCheckpointFiles(ctx context.Context, sessionID string, files map[string][]byte) error {
47		target, err := cursorTargetPaths(sessionID)
48		if err != nil {
49			return err
50		}
51	
52		if data, ok := files[ChatArchiveFilename]; ok {
53			return restoreV3(ctx, target, data)
54		}
55		if data, ok := files[sessionID+ChatArchiveFilenameV2]; ok {
56			return restoreV2(target, data)
57		}
58		return nil
59	}
60	
61	// cursorTarget holds the paths we write into for a given session.
62	type cursorTarget struct {
63		agentID   string
64		storeDB   string // ~/.cursor/chats/<hash>/<agent-id>/store.db
65		nestedJSO string // ~/.cursor/projects/<slug>/agent-transcripts/<agent-id>/<agent-id>.jsonl
66	}
67	
68	// cursorTargetPaths resolves cursor's on-disk layout for the current cwd.
69	// Cursor resolves symlinks when computing its workspace hash (e.g. /tmp → /private/tmp
70	// on macOS), so we match that before hashing/slugifying.
71	func cursorTargetPaths(sessionID string) (cursorTarget, error) {
72		home, err := os.UserHomeDir()
73		if err != nil {
74			return cursorTarget{}, fmt.Errorf("home directory: %w", err)
75		}
76		cwd, err := os.Getwd() //nolint:forbidigo // Cursor's MD5(project_path) uses cwd, not git root
77		if err != nil {
78			return cursorTarget{}, fmt.Errorf("current directory: %w", err)
79		}
80		if resolved, evalErr := filepath.EvalSymlinks(cwd); evalErr == nil {
81			cwd = resolved
82		}
83		hash := WorkspaceHash(cwd)
84		slug := WorkspaceSlug(cwd)
85		return cursorTarget{
86			agentID:   sessionID,
87			storeDB:   filepath.Join(home, ".cursor", "chats", hash, sessionID, "store.db"),
88			nestedJSO: filepath.Join(home, ".cursor", "projects", slug, "agent-transcripts", sessionID, sessionID+".jsonl"),
89		}, nil
90	}
91	
92	// restoreV3 rebuilds store.db from a JSONL dump.
93	func restoreV3(ctx context.Context, t cursorTarget, data []byte) error {
94		if err := os.MkdirAll(filepath.Dir(t.storeDB), 0o750); err != nil {
95			return fmt.Errorf("chats dir: %w", err)
96		}
97		// Remove any prior DB + sidecars so sqlite creates a fresh file with no
98		// WAL state bleeding through from a stale session.
99		for _, p := range []string{t.storeDB, t.storeDB + "-wal", t.storeDB + "-shm"} {
100			if err := os.Remove(p); err != nil && !os.IsNotExist(err) {
101				return fmt.Errorf("clearing %s: %w", filepath.Base(p), err)
102			}
103		}
104	
105		db, err := sql.Open("sqlite", t.storeDB)
106		if err != nil {
107			return fmt.Errorf("open sqlite: %w", err)
108		}
109		defer db.Close()
110	
111		// Force DELETE journal mode so all writes land in the main DB file,
112		// not in a WAL sidecar. Without this modernc.org/sqlite defaults to WAL
113		// mode; rows would sit in store.db-wal and other SQLite clients (e.g.
114		// cursor-agent itself) may fail to read them back when the main file is
115		// still the initial empty page.
116		if _, err := db.ExecContext(ctx, "PRAGMA journal_mode=DELETE;"); err != nil {
117			return fmt.Errorf("set journal_mode: %w", err)
118		}
119	
120		if _, err := db.ExecContext(ctx, `
121			CREATE TABLE meta  (key TEXT PRIMARY KEY, value TEXT);
122			CREATE TABLE blobs (id  TEXT PRIMARY KEY, data BLOB);
123		`); err != nil {
124			return fmt.Errorf("create tables: %w", err)
125		}
126	
127		tx, err := db.BeginTx(ctx, nil)
128		if err != nil {
129			return fmt.Errorf("begin: %w", err)
130		}
131		defer tx.Rollback() //nolint:errcheck // Commit() supersedes
132	
133		scanner := bufio.NewScanner(bytes.NewReader(data))
134		// Blobs can be larger than bufio.Scanner's default 64 KB line cap.
135		// SQLite row size is effectively unbounded for our inputs; 8 MB is
136		// comfortably above any single cursor blob we expect.
137		scanner.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
138	
139		lineNum := 0
140		for scanner.Scan() {
141			lineNum++
142			line := scanner.Bytes()
143			if len(bytes.TrimSpace(line)) == 0 {
144				continue
145			}
146			var row jsonlLine
147			if err := json.Unmarshal(line, &row); err != nil {
148				return fmt.Errorf("parse line %d: %w", lineNum, err)
149			}
150			switch row.T {
151			case "meta":
152				if err := insertMetaRow(ctx, tx, row); err != nil {
153					return fmt.Errorf("line %d: %w", lineNum, err)
154				}
155			case "blob":
156				if err := insertBlobRow(ctx, tx, row); err != nil {
157					return fmt.Errorf("line %d: %w", lineNum, err)
158				}
159			default:
160				return fmt.Errorf("line %d: unknown row type %q", lineNum, row.T)
161			}
162		}
163		if err := scanner.Err(); err != nil {
164			return fmt.Errorf("read archive: %w", err)
165		}
166		if err := tx.Commit(); err != nil {
167			return fmt.Errorf("commit: %w", err)
168		}
169		return nil
170	}
171	
172	func insertMetaRow(ctx context.Context, tx *sql.Tx, row jsonlLine) error {
173		// Cursor's meta.value is stored as hex-ASCII of the JSON bytes; preserve
174		// that shape so cursor reads the same format it wrote.
175		if len(row.V) == 0 {
176			return errors.New("meta row missing v")
177		}
178		if _, err := tx.ExecContext(ctx,
179			"INSERT INTO meta(key, value) VALUES(?, ?)",
180			row.K, hex.EncodeToString(row.V),
181		); err != nil {
182			return fmt.Errorf("insert meta: %w", err)
183		}
184		return nil
185	}
186	
187	func insertBlobRow(ctx context.Context, tx *sql.Tx, row jsonlLine) error {
188		raw, err := base64.StdEncoding.DecodeString(row.Data)
189		if err != nil {
190			return fmt.Errorf("decode blob data: %w", err)
191		}
192		if _, err := tx.ExecContext(ctx,
193			"INSERT INTO blobs(id, data) VALUES(?, ?)",
194			row.ID, raw,
195		); err != nil {
196			return fmt.Errorf("insert blob: %w", err)
197		}
198		return nil
199	}
200	
201	// restoreV2 keeps the legacy opaque-base64 restore path alive for already-
202	// pushed checkpoints that predate v3. When the metadata branch ages out
203	// past the last v2 checkpoint, this function and ChatArchive can be removed.
204	func restoreV2(t cursorTarget, data []byte) error {
205		var archive ChatArchive
206		if err := json.Unmarshal(data, &archive); err != nil {
207			return fmt.Errorf("decoding v2 cursor archive: %w", err)
208		}
209		if archive.Format != archiveFormat {
210			return fmt.Errorf("unexpected v2 archive format %q", archive.Format)
211		}
212		if archive.Version != 2 {
213			return fmt.Errorf("unsupported v2 archive version %d", archive.Version)
214		}
215	
216		if err := os.MkdirAll(filepath.Dir(t.storeDB), 0o750); err != nil {
217			return fmt.Errorf("creating chats directory: %w", err)
218		}
219		if err := writeBase64(archive.DBBytes, t.storeDB); err != nil {
220			return fmt.Errorf("writing store.db: %w", err)
221		}
222		for _, pair := range []struct {
223			b64, path string
224		}{
225			{archive.DBWALBytes, t.storeDB + "-wal"},
226			{archive.DBSHMBytes, t.storeDB + "-shm"},
227		} {
228			if pair.b64 == "" {
229				_ = os.Remove(pair.path)
230				continue
231			}
232			if err := writeBase64(pair.b64, pair.path); err != nil {
233				return fmt.Errorf("writing %s: %w", filepath.Base(pair.path), err)
234			}
235		}
236	
237		if len(archive.Transcript) > 0 {
238			if err := os.MkdirAll(filepath.Dir(t.nestedJSO), 0o750); err != nil {
239				return fmt.Errorf("creating transcripts directory: %w", err)
240			}
241			if err := writeTranscript(archive.Transcript, t.nestedJSO); err != nil {
242				return fmt.Errorf("writing transcript: %w", err)
243			}
244		}
245		return nil
246	}
247	
248	func writeBase64(b64, targetPath string) error {
249		raw, err := base64.StdEncoding.DecodeString(b64)
250		if err != nil {
251			return fmt.Errorf("base64: %w", err)
252		}
253		if err := os.WriteFile(targetPath, raw, 0o600); err != nil {
254			return fmt.Errorf("write %s: %w", targetPath, err)
255		}
256		return nil
257	}
258	
259	func writeTranscript(entries []json.RawMessage, targetPath string) error {
260		f, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) //nolint:gosec // path under ~/.cursor
261		if err != nil {
262			return fmt.Errorf("open: %w", err)
263		}
264		defer f.Close()
265		for _, entry := range entries {
266			if _, err := f.Write(entry); err != nil {
267				return fmt.Errorf("write entry: %w", err)
268			}
269			if _, err := f.WriteString("\n"); err != nil {
270				return fmt.Errorf("write newline: %w", err)
271			}
272		}
273		return nil
274	}
