1	package cursor
2	
3	import (
4		"bytes"
5		"context"
6		"database/sql"
7		"encoding/base64"
8		"encoding/hex"
9		"encoding/json"
10		"errors"
11		"fmt"
12		"io"
13		"os"
14		"path/filepath"
15		"sort"
16	
17		"github.com/entireio/cli/redact"
18	
19		_ "modernc.org/sqlite" // pure-Go SQLite driver registered as "sqlite"
20	)
21	
22	// Archive v3 ships cursor's `store.db` as a JSONL dump of its two tables
23	// (meta + blobs). Each line is a JSON object carrying one row. Restore
24	// replays the rows into a fresh SQLite file, so cursor opens the same
25	// content-addressable DAG it wrote. Plain-text content gives git's pack
26	// compression something to chew on and keeps per-checkpoint size down
27	// to a few kB versus ~340 kB for the v2 opaque-base64 format.
28	const (
29		archiveFormat = "cursor-chat-export"
30	
31		// ChatArchiveFilename is the filename used inside a session's metadata
32		// directory to carry cursor's JSONL dump. A single archive belongs to
33		// exactly one session, so we don't repeat the session id in the name.
34		ChatArchiveFilename = "cursor-chat.jsonl"
35	
36		// ChatArchiveFilenameV2 is the legacy opaque-base64 format still readable
37		// on restore (the metadata branch may contain pre-v3 checkpoints until
38		// they age out).
39		ChatArchiveFilenameV2 = ".cursor-chat.json"
40	)
41	
42	// ChatArchive is the v2 archive shape kept around for backward-compatible
43	// reads of already-pushed checkpoints. New checkpoints use JSONL (v3).
44	//
45	// DBPath and TranscriptPath were absolute filesystem paths captured at v2
46	// export time. v3 export does not populate them (the format is JSONL, not
47	// this struct). Old archives on the metadata branch may still carry those
48	// paths until they age out — restore code reads them but never writes them.
49	type ChatArchive struct {
50		Format         string            `json:"format"`
51		Version        int               `json:"version"`
52		AgentID        string            `json:"agentId"`
53		DBPath         string            `json:"db_path,omitempty"`         // legacy v2; never set by v3.
54		DBBytes        string            `json:"db_bytes,omitempty"`        // legacy v2; never set by v3.
55		DBWALBytes     string            `json:"db_wal_bytes,omitempty"`    // legacy v2; never set by v3.
56		DBSHMBytes     string            `json:"db_shm_bytes,omitempty"`    // legacy v2; never set by v3.
57		TranscriptPath string            `json:"transcript_path,omitempty"` // legacy v2; never set by v3.
58		Transcript     []json.RawMessage `json:"transcript,omitempty"`      // legacy v2; never set by v3.
59	}
60	
61	// jsonlLine is one row in the v3 archive. `t` discriminates meta vs blob;
62	// other fields apply conditionally. Stored sorted by (t, id) so git pack
63	// deltas across checkpoints capture only the newly added blob rows.
64	type jsonlLine struct {
65		T    string          `json:"t"`
66		K    string          `json:"k,omitempty"`
67		V    json.RawMessage `json:"v,omitempty"`
68		ID   string          `json:"id,omitempty"`
69		Data string          `json:"data,omitempty"`
70	}
71	
72	// ExportChatArchive reads the live cursor store.db for agentID, absorbs any
73	// pending WAL frames, and returns a JSONL dump of its meta + blobs tables.
74	// Returns (nil, os.ErrNotExist) if cursor has no DB yet for this agent.
75	func ExportChatArchive(ctx context.Context, agentID string) ([]byte, error) {
76		dbPath, err := findStoreDB(agentID)
77		if err != nil {
78			return nil, err
79		}
80	
81		workDir, err := os.MkdirTemp("", "entire-cursor-export-*")
82		if err != nil {
83			return nil, fmt.Errorf("temp dir: %w", err)
84		}
85		defer os.RemoveAll(workDir)
86	
87		stagedPath := filepath.Join(workDir, "store.db")
88		if err := copyDBWithSidecars(dbPath, stagedPath); err != nil {
89			return nil, fmt.Errorf("staging store.db: %w", err)
90		}
91	
92		return dumpJSONL(ctx, stagedPath)
93	}
94	
95	// findStoreDB searches ~/.cursor/chats/*/<agentID>/store.db. Returns
96	// os.ErrNotExist (wrapped) if cursor hasn't created a DB yet.
97	func findStoreDB(agentID string) (string, error) {
98		home, err := os.UserHomeDir()
99		if err != nil {
100			return "", fmt.Errorf("home dir: %w", err)
101		}
102		chatsDir := filepath.Join(home, ".cursor", "chats")
103		dbPath, err := findOne(filepath.Join(chatsDir, "*", agentID, "store.db"))
104		if err != nil {
105			return "", fmt.Errorf("glob store.db: %w", err)
106		}
107		if dbPath == "" {
108			return "", fmt.Errorf("no store.db for agent %q: %w", agentID, os.ErrNotExist)
109		}
110		return dbPath, nil
111	}
112	
113	// copyDBWithSidecars copies store.db plus its -wal and -shm sidecars into
114	// dst (dst is the target store.db path). Sidecars get the same stem. The
115	// copy lets us checkpoint WAL without touching cursor's live files, which
116	// cursor may still have open.
117	func copyDBWithSidecars(src, dst string) error {
118		if err := copyFile(src, dst); err != nil {
119			return err
120		}
121		for _, suffix := range []string{"-wal", "-shm"} {
122			if err := copyFile(src+suffix, dst+suffix); err != nil && !errors.Is(err, os.ErrNotExist) {
123				return fmt.Errorf("copying %s: %w", suffix, err)
124			}
125		}
126		return nil
127	}
128	
129	func copyFile(src, dst string) error {
130		// Real byte copy, not a hardlink — sqlite's wal_checkpoint(TRUNCATE) and any
131		// other writes during dump must not touch cursor's live store.db/-wal/-shm.
132		in, err := os.Open(src) //nolint:gosec // cursor-managed path
133		if err != nil {
134			return fmt.Errorf("open %s: %w", src, err)
135		}
136		defer in.Close()
137		out, err := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) //nolint:gosec // dst is our own temp path
138		if err != nil {
139			return fmt.Errorf("create %s: %w", dst, err)
140		}
141		defer out.Close()
142		if _, err := io.Copy(out, in); err != nil {
143			return fmt.Errorf("copying bytes: %w", err)
144		}
145		return nil
146	}
147	
148	// dumpJSONL opens dbPath (a copy), runs wal_checkpoint, and emits JSONL.
149	func dumpJSONL(ctx context.Context, dbPath string) ([]byte, error) {
150		db, err := sql.Open("sqlite", dbPath)
151		if err != nil {
152			return nil, fmt.Errorf("open sqlite: %w", err)
153		}
154		defer db.Close()
155	
156		// Consolidate any pending WAL frames into the main DB so our SELECTs see
157		// the latest state. TRUNCATE resets the WAL file to size 0 on disk; we
158		// discard the copy anyway, but the PRAGMA also makes the DB reads cheaper.
159		if _, err := db.ExecContext(ctx, "PRAGMA wal_checkpoint(TRUNCATE);"); err != nil {
160			return nil, fmt.Errorf("wal_checkpoint: %w", err)
161		}
162	
163		var buf bytes.Buffer
164		enc := json.NewEncoder(&buf)
165	
166		if err := writeMetaLines(ctx, db, enc); err != nil {
167			return nil, err
168		}
169		if err := writeBlobLines(ctx, db, enc); err != nil {
170			return nil, err
171		}
172		return buf.Bytes(), nil
173	}
174	
175	func writeMetaLines(ctx context.Context, db *sql.DB, enc *json.Encoder) error {
176		rows, err := db.QueryContext(ctx, "SELECT key, value FROM meta ORDER BY key")
177		if err != nil {
178			return fmt.Errorf("select meta: %w", err)
179		}
180		defer rows.Close()
181		for rows.Next() {
182			var key, value string
183			if err := rows.Scan(&key, &value); err != nil {
184				return fmt.Errorf("scan meta: %w", err)
185			}
186			// Cursor stores meta.value as hex-encoded ASCII JSON. Decode so the
187			// archive is human-readable and redactor-friendly; restore re-encodes.
188			decoded, err := hex.DecodeString(value)
189			if err != nil {
190				return fmt.Errorf("hex-decode meta[%s]: %w", key, err)
191			}
192			if !json.Valid(decoded) {
193				return fmt.Errorf("meta[%s] value is not valid JSON after hex decode", key)
194			}
195			if err := enc.Encode(jsonlLine{T: "meta", K: key, V: json.RawMessage(decoded)}); err != nil {
196				return fmt.Errorf("encode meta line: %w", err)
197			}
198		}
199		if err := rows.Err(); err != nil {
200			return fmt.Errorf("iterate meta: %w", err)
201		}
202		return nil
203	}
204	
205	func writeBlobLines(ctx context.Context, db *sql.DB, enc *json.Encoder) error {
206		// Pull rows and sort in Go by id — gives deterministic output regardless
207		// of sqlite row ordering and helps git pack dedupe across checkpoints.
208		rows, err := db.QueryContext(ctx, "SELECT id, data FROM blobs")
209		if err != nil {
210			return fmt.Errorf("select blobs: %w", err)
211		}
212		defer rows.Close()
213	
214		type blobRow struct {
215			id   string
216			data []byte
217		}
218		var collected []blobRow
219		for rows.Next() {
220			var r blobRow
221			if err := rows.Scan(&r.id, &r.data); err != nil {
222				return fmt.Errorf("scan blob: %w", err)
223			}
224			collected = append(collected, r)
225		}
226		if err := rows.Err(); err != nil {
227			return fmt.Errorf("iterate blobs: %w", err)
228		}
229		sort.Slice(collected, func(i, j int) bool { return collected[i].id < collected[j].id })
230		for _, r := range collected {
231			redacted := redactBlobData(r.data)
232			if err := enc.Encode(jsonlLine{
233				T:    "blob",
234				ID:   r.id,
235				Data: base64.StdEncoding.EncodeToString(redacted),
236			}); err != nil {
237				return fmt.Errorf("encode blob line: %w", err)
238			}
239		}
240		return nil
241	}
242	
243	// redactBlobData strips secrets out of cursor chat-message blobs before they
244	// go into a checkpoint. Cursor's blobs come in three shapes:
245	//
246	//  1. {"role": "...", "content": "<text>"} or content as typed array — chat
247	//     messages and tool calls. Walk the JSON tree, redacting every string
248	//     value (covers nested input.contents on tool_use parts).
249	//  2. Merkle tree nodes — top-level JSON without a "role" key, referencing
250	//     child blob IDs by content-addressed SHA256. Left untouched so the
251	//     DAG roundtrips exactly.
252	//  3. Cursor-wrapped frames (protobuf-like envelope around the inner
253	//     payload, e.g. user prompts can land in a length-prefixed wire format,
254	//     and assistant replies sometimes ride inside an encrypted prefix).
255	//     Not JSON, but the secret-bearing text appears in cleartext within the
256	//     wrapper. Fall back to redact.Bytes for byte-level scrubbing.
257	//
258	// The opaque-archive redaction bypass in the checkpoint walker already keeps
259	// git from corrupting these on commit; redactBlobData is what gives us the
260	// chat-content secret scrubbing the bypass would otherwise prevent.
261	func redactBlobData(data []byte) []byte {
262		var doc map[string]any
263		if err := json.Unmarshal(data, &doc); err == nil {
264			if _, hasRole := doc["role"]; !hasRole {
265				return data
266			}
267			redactJSONStrings(doc)
268			out, err := json.Marshal(doc)
269			if err != nil {
270				return data
271			}
272			return out
273		}
274		// Cursor-wrapped binary frame: scrub at the byte level. Slightly less
275		// surgical than the JSON walk above (replaces every secret-pattern match
276		// in raw bytes, including inside any embedded JSON the wrapper carries)
277		// but correct for the user-prompt protobuf frames we observed in the
278		// real cursor DB.
279		return redact.Bytes(data)
280	}
281	
282	// redactJSONStrings walks v in place and applies redact.String to every
283	// string value reachable through map values or array elements. Used by
284	// redactBlobData to scrub chat-message JSON, where any string value is
285	// potentially user-supplied prompt or tool-call argument content.
286	func redactJSONStrings(v any) {
287		switch value := v.(type) {
288		case map[string]any:
289			for k, child := range value {
290				if s, ok := child.(string); ok {
291					value[k] = redact.String(s)
292					continue
293				}
294				redactJSONStrings(child)
295			}
296		case []any:
297			for i, child := range value {
298				if s, ok := child.(string); ok {
299					value[i] = redact.String(s)
300					continue
301				}
302				redactJSONStrings(child)
303			}
304		}
305	}
