1765	// writeExtraFilesToEntries adds agent-contributed extras (e.g. cursor-chat.jsonl)
1766	// as blobs in the entries map under sessionPath. Reused by both WriteCommitted
1767	// (initial write) and UpdateCommitted (refresh on Finalize); v1 and v2 stores
1768	// share the helper so the loop body stays in one place.
1769	//
1770	// Rejects relPaths that would escape the session directory (absolute paths,
1771	// "..", or any path separator) so a malicious or buggy contributor can't
1772	// overwrite files outside its own namespace or replace standard checkpoint
1773	// metadata files.
1774	func writeExtraFilesToEntries(repo *git.Repository, entries map[string]object.TreeEntry, sessionPath string, extras map[string][]byte) error {
1775		for relPath, content := range extras {
1776			if err := validateExtraFileRelPath(relPath); err != nil {
1777				return err
1778			}
1779			blobHash, err := CreateBlobFromContent(repo, content)
1780			if err != nil {
1781				return fmt.Errorf("failed to create blob for extra file %s: %w", relPath, err)
1782			}
1783			entries[sessionPath+relPath] = object.TreeEntry{
1784				Name: sessionPath + relPath,
1785				Mode: filemode.Regular,
1786				Hash: blobHash,
1787			}
1788		}
1789		return nil
1790	}
