1792	// validateExtraFileRelPath rejects any relPath that could escape the session
1793	// subdirectory. Agent-contributed extras live in a flat namespace; we don't
1794	// allow nested directories or traversal segments.
1795	func validateExtraFileRelPath(relPath string) error {
1796		if relPath == "" {
1797			return errors.New("extra file relPath is empty")
1798		}
1799		if path.IsAbs(relPath) || strings.HasPrefix(relPath, "/") {
1800			return fmt.Errorf("extra file relPath is absolute: %q", relPath)
1801		}
1802		if strings.ContainsAny(relPath, "/\\") {
1803			return fmt.Errorf("extra file relPath contains a path separator: %q", relPath)
1804		}
1805		if relPath == "." || relPath == ".." || strings.Contains(relPath, "..") {
1806			return fmt.Errorf("extra file relPath contains a traversal segment: %q", relPath)
1807		}
1808		return nil
1809	}
