1811	// isOpaqueAgentArchive reports whether a tree path belongs to an agent-contributed
1812	// opaque archive. These carry binary blobs (e.g. SQLite rows) as base64 substrings,
1813	// either inside one JSON document (v2: .cursor-chat.json) or inside JSONL rows
1814	// (v3: cursor-chat.jsonl). Either way the redactor's secret-pattern substitutions
1815	// would corrupt the base64 payload, so we skip redaction and trust the upstream
1816	// producer (the cursor DB content is chat text; secrets in there belong to the
1817	// user and weren't written by us).
1818	//
1819	// Kept here (rather than behind an interface) because the checkpoint package
1820	// otherwise has no reason to know about specific agent file formats; the list
1821	// stays short as long as agents prefer binary-friendly archive formats.
1822	func isOpaqueAgentArchive(treePath string) bool {
1823		return strings.HasSuffix(treePath, ".cursor-chat.json") ||
1824			strings.HasSuffix(treePath, "cursor-chat.jsonl")
1825	}
