64	// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
65	// fires state machine transition.
66	func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
67		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
68		logging.Info(logCtx, "session-start",
69			slog.String("event", event.Type.String()),
70			slog.String("session_id", event.SessionID),
71			slog.String("session_ref", event.SessionRef),
72			slog.String("model", event.Model),
73		)
74	
75		if event.SessionID == "" {
76			return fmt.Errorf("no session_id in %s event", event.Type)
77		}
78		if err := validation.ValidateSessionID(event.SessionID); err != nil {
79			return fmt.Errorf("invalid %s event: %w", event.Type, err)
80		}
81	
82		// Build informational message — warn early if repo has no commits yet,
83		// since checkpoints require at least one commit to work.
84		message := sessionStartMessage(ag.Name(), false)
85		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
86			message = sessionStartMessage(ag.Name(), true)
87		}
88	
89		// Check for concurrent sessions and append count if any
90		_, countSessionsSpan := perf.Start(ctx, "count_active_sessions")
91		strat := GetStrategy(ctx)
92		if count, err := strat.CountOtherActiveSessionsWithCheckpoints(ctx, event.SessionID); err == nil && count > 0 {
93			if ag.Name() == agent.AgentNameCodex {
94				message += fmt.Sprintf(" %d other active conversation(s) in this workspace will also be included. Use 'entire status' for more information.", count)
95			} else {
96				message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
97			}
98		}
99		countSessionsSpan.End()
100	
101		// Output informational message if the agent supports hook responses.
102		// Claude Code reads JSON from stdout; agents that don't implement
103		// HookResponseWriter silently skip (avoids raw JSON in their terminal).
104		_, hookResponseSpan := perf.Start(ctx, "write_hook_response")
105		if event.ResponseMessage != "" {
106			message = event.ResponseMessage
107		}
108		if writer, ok := agent.AsHookResponseWriter(ag); ok {
109			if err := writer.WriteHookResponse(message); err != nil {
110				hookResponseSpan.RecordError(err)
111				hookResponseSpan.End()
112				return fmt.Errorf("failed to write hook response: %w", err)
113			}
114		}
115		hookResponseSpan.End()
116	
117		// Store model hint if the agent provided model info on SessionStart
118		if event.Model != "" {
119			if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
120				logging.Warn(logCtx, "failed to store model hint on session start",
121					slog.String("error", err.Error()))
122			}
123		}
124	
125		// Fire EventSessionStart for the current session (if state exists).
126		if state, loadErr := strategy.LoadSessionState(ctx, event.SessionID); loadErr != nil {
127			logging.Warn(logCtx, "failed to load session state on start",
128				slog.String("error", loadErr.Error()))
129		} else if state != nil {
130			persistEventMetadataToState(event, state)
131			if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
132				logging.Warn(logCtx, "session start transition failed",
133					slog.String("error", transErr.Error()))
134			}
135			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
136				logging.Warn(logCtx, "failed to update session state on start",
137					slog.String("error", saveErr.Error()))
138			}
139		}
140	
141		return nil
142	}
