158	// handleLifecycleModelUpdate persists the model name for the current session.
159	//
160	// If the session state file already exists (e.g., Gemini's BeforeModel fires
161	// after TurnStart), the model is written directly to state.ModelName — no hint
162	// file needed. Otherwise falls back to StoreModelHint for cross-process
163	// persistence (see its doc comment for the full rationale).
164	func handleLifecycleModelUpdate(ctx context.Context, ag agent.Agent, event *agent.Event) error {
165		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
166		logging.Info(logCtx, "model-update",
167			slog.String("session_id", event.SessionID),
168			slog.String("model", event.Model),
169		)
170	
171		if event.SessionID == "" || event.Model == "" {
172			return nil
173		}
174	
175		// Prefer writing directly to session state when it exists
176		state, loadErr := strategy.LoadSessionState(ctx, event.SessionID)
177		if loadErr != nil {
178			logging.Debug(logCtx, "could not load session state for model update, using hint file",
179				slog.String("error", loadErr.Error()))
180		}
181		if loadErr == nil && state != nil {
182			state.ModelName = event.Model
183			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
184				logging.Warn(logCtx, "failed to update session state with model",
185					slog.String("error", saveErr.Error()))
186			}
187			return nil
188		}
189	
190		// State doesn't exist yet (or failed to load) — use hint file (see StoreModelHint doc)
191		if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
192			logging.Warn(logCtx, "failed to store model hint",
193				slog.String("error", err.Error()))
194		}
195	
196		return nil
197	}
