199	// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
200	// ensures strategy setup, initializes session.
201	func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
202		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
203		logging.Info(logCtx, "turn-start",
204			slog.String("event", event.Type.String()),
205			slog.String("session_id", event.SessionID),
206			slog.String("session_ref", event.SessionRef),
207			slog.String("model", event.Model),
208		)
209	
210		sessionID := event.SessionID
211		if sessionID == "" {
212			return fmt.Errorf("no session_id in %s event", event.Type)
213		}
214		if err := validation.ValidateSessionID(sessionID); err != nil {
215			return fmt.Errorf("invalid %s event: %w", event.Type, err)
216		}
217	
218		// Fill model from hint file if the agent didn't provide it on this hook
219		if event.Model == "" {
220			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
221				event.Model = hint
222				logging.Debug(logCtx, "loaded model from hint file",
223					slog.String("model", hint))
224			}
225		}
226	
227		// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
228		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
229		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
230			captureSpan.RecordError(err)
231			captureSpan.End()
232			return err
233		}
234		captureSpan.End()
235	
236		// Append prompt to prompt.txt on filesystem so it's available for
237		// mid-turn commits (before SaveStep writes it to the shadow branch).
238		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
239		if event.Prompt != "" {
240			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
241			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
242				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
243					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
244					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
245					var content string
246					if readErr == nil && len(existing) > 0 {
247						content = string(existing) + "\n\n---\n\n" + event.Prompt
248					} else {
249						content = event.Prompt
250					}
251					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
252						logging.Warn(logCtx, "failed to write prompt.txt",
253							slog.String("error", writeErr.Error()))
254					}
255				}
256			}
257		}
258	
259		// Ensure strategy setup and initialize session
260		_, initSpan := perf.Start(ctx, "init_session")
261		if err := strategy.EnsureSetup(ctx); err != nil {
262			logging.Warn(logCtx, "failed to ensure strategy setup",
263				slog.String("error", err.Error()))
264		}
265	
266		strat := GetStrategy(ctx)
267		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
268			logging.Warn(logCtx, "failed to initialize session state",
269				slog.String("error", err.Error()))
270		}
271		initSpan.End()
272	
273		return nil
274	}
275	
276	// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
277	// detects file changes, saves step + checkpoint, transitions phase.
278	//
279	//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
280	func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
281		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
282		logging.Info(logCtx, "turn-end",
283			slog.String("event", event.Type.String()),
284			slog.String("session_id", event.SessionID),
285			slog.String("session_ref", event.SessionRef),
286			slog.String("model", event.Model),
287		)
288	
289		sessionID := event.SessionID
290		if sessionID == "" {
291			sessionID = unknownSessionID
292		}
293	
294		// Fill model from hint file if the agent didn't provide it on this hook
295		if event.Model == "" && sessionID != unknownSessionID {
296			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
297				event.Model = hint
298				logging.Debug(logCtx, "loaded model from hint file",
299					slog.String("model", hint))
300			}
301		}
302	
303		transcriptRef := event.SessionRef
304		if transcriptRef == "" {
305			return errors.New("transcript file not specified")
306		}
307	
308		// If agent implements TranscriptPreparer, materialize the transcript file.
309		// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
310		// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
311		// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
312		// TranscriptPreparer (Gemini, Droid) are unaffected.
313		_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
314		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
315			if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
316				logging.Warn(logCtx, "failed to prepare transcript",
317					slog.String("error", err.Error()))
318			}
319		}
320	
321		if !fileExists(transcriptRef) {
322			prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
323			prepareSpan.End()
324			return fmt.Errorf("transcript file not found: %s", transcriptRef)
325		}
326	
327		// Early check: bail out quickly if the repo has no commits yet.
328		// Return nil (not an error) so the hook exits 0 — agents treat non-zero
329		// exit codes as hook failures. The user was already warned at session start.
330		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
331			prepareSpan.End()
332			logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
333			return nil
334		}
335		prepareSpan.End()
336	
337		// Create session metadata directory
338		_, copySpan := perf.Start(ctx, "copy_transcript")
339		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
340		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
341		if err != nil {
342			sessionDirAbs = sessionDir
343		}
344		if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
345			copySpan.RecordError(err)
346			copySpan.End()
347			return fmt.Errorf("failed to create session directory: %w", err)
348		}
349	
350		// Copy transcript to session directory
351		transcriptData, err := ag.ReadTranscript(transcriptRef)
352		if err != nil {
353			copySpan.RecordError(err)
354			copySpan.End()
355			return fmt.Errorf("failed to read transcript: %w", err)
356		}
357		logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
358		if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
359			copySpan.RecordError(err)
360			copySpan.End()
361			return fmt.Errorf("failed to write transcript: %w", err)
362		}
363		logging.Debug(logCtx, "copied transcript",
364			slog.String("path", sessionDir+"/"+paths.TranscriptFileName))
365		copySpan.End()
366	
367		// Load pre-prompt state (captured on TurnStart)
368		_, extractSpan := perf.Start(ctx, "extract_metadata")
369		preState, err := LoadPrePromptState(ctx, sessionID)
370		if err != nil {
371			logging.Warn(logCtx, "failed to load pre-prompt state",
372				slog.String("error", err.Error()))
373		}
374	
375		// Determine transcript offset
376		transcriptOffset := resolveTranscriptOffset(ctx, preState, sessionID)
377	
378		// Backfill prompt.txt from transcript when prompt data is missing.
379		// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
380		// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
381		// there genuinely were no prompts. We track whether backfill occurred so we can
382		// update session state after SaveStep (which may reinitialize state).
383		var backfilledPrompt string
384		promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
385		existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
386		if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
387			logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
388				slog.String("error", readPromptErr.Error()))
389		} else if len(existingPrompt) == 0 {
390			if extractor, ok := agent.AsPromptExtractor(ag); ok {
391				prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
392				if extractErr != nil {
393					logging.Warn(logCtx, "failed to extract prompts from transcript",
394						slog.String("error", extractErr.Error()))
395				} else if len(prompts) > 0 {
396					content := strings.Join(prompts, "\n\n---\n\n")
397					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
398						logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
399							slog.String("error", writeErr.Error()))
400					} else {
401						logging.Debug(logCtx, "backfilled prompt.txt from transcript",
402							slog.Int("prompt_count", len(prompts)))
403						backfilledPrompt = prompts[len(prompts)-1]
404					}
405				}
406			}
407		}
408	
409		// Compute subagents directory for agents that support subagent extraction.
410		// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
411		subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
412	
413		// Extract metadata via agent interface (modified files)
414		var modifiedFiles []string
415	
416		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
417			// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
418			if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
419				if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
420					logging.Warn(logCtx, "failed to extract modified files (with subagents)",
421						slog.String("error", fileErr.Error()))
422				} else {
423					modifiedFiles = files
424				}
425			} else {
426				// Fall back to basic extraction (main transcript only)
427				if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
428					logging.Warn(logCtx, "failed to extract modified files",
429						slog.String("error", fileErr.Error()))
430				} else {
431					modifiedFiles = files
432				}
433			}
434		}
435		extractSpan.End()
436	
437		// Generate commit message from last prompt (read from session state, set at TurnStart).
438		// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
439		// Fall back to backfilledPrompt extracted from the transcript.
440		// Single load serves both prompt retrieval and backfill.
441		_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
442		lastPrompt := ""
443		if sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && sessionState != nil {
444			lastPrompt = sessionState.LastPrompt
445			// Backfill LastPrompt so `entire status` shows the prompt even when
446			// no files were modified (before the early return below).
447			if lastPrompt == "" && backfilledPrompt != "" {
448				lastPrompt = backfilledPrompt
449				sessionState.LastPrompt = backfilledPrompt
450				if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
451					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
452						slog.String("error", saveErr.Error()))
453				}
454			}
455		} else if backfilledPrompt != "" {
456			lastPrompt = backfilledPrompt
457		}
458		commitMessage := generateCommitMessage(lastPrompt, ag.Type())
459		logging.Debug(logCtx, "using commit message",
460			slog.Int("message_length", len(commitMessage)))
461		commitMsgSpan.End()
462	
463		// Get worktree root for path normalization
464		_, detectSpan := perf.Start(ctx, "detect_file_changes")
465		repoRoot, err := paths.WorktreeRoot(ctx)
466		if err != nil {
467			detectSpan.RecordError(err)
468			detectSpan.End()
469			return fmt.Errorf("failed to get worktree root: %w", err)
470		}
471	
472		var preUntrackedFiles []string
473		if preState != nil {
474			logging.Debug(logCtx, "pre-prompt state",
475				slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
476			preUntrackedFiles = preState.PreUntrackedFiles()
477		}
478	
479		// Detect file changes via git status
480		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
481		if err != nil {
482			logging.Warn(logCtx, "failed to compute file changes",
483				slog.String("error", err.Error()))
484		}
485		detectSpan.End()
486	
487		// Filter and normalize all paths
488		_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
489		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
490		var relNewFiles, relDeletedFiles []string
491		if changes != nil {
492			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
493			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
494	
495			// Merge git-status modified files as a fallback for transcript parsing.
496			// Transcript parsing is the primary source for modified files, but it can miss
497			// files if the agent uses an unrecognized tool or the transcript format changes.
498			// Git status catches any tracked file with working-tree changes.
499			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
500		}
501	
502		// Filter transcript-extracted files to exclude files already committed to HEAD.
503		// When an agent commits files mid-turn, those files are condensed by PostCommit
504		// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
505		// if it exists in HEAD with the same content as the working tree.
506		relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
507	
508		// Drop gitignored entries before deciding whether to save a shadow checkpoint.
509		// After a mid-turn commit, git status often reports untracked-but-ignored noise
510		// (e.g. .DS_Store) that would otherwise keep totalChanges > 0 and force a
511		// shadow checkpoint with no real delta beyond metadata dir bookkeeping.
512		if repo, repoErr := openRepository(ctx); repoErr == nil {
513			relModifiedFiles = checkpoint.FilterGitIgnoredFiles(ctx, repo, relModifiedFiles)
514			relNewFiles = checkpoint.FilterGitIgnoredFiles(ctx, repo, relNewFiles)
515			relDeletedFiles = checkpoint.FilterGitIgnoredFiles(ctx, repo, relDeletedFiles)
516		}
517		normalizeSpan.End()
518	
519		// Check if there are any changes
520		totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
521		if totalChanges == 0 {
522			logging.Info(logCtx, "no files modified during session, skipping checkpoint")
523			transitionSessionTurnEnd(ctx, sessionID, event)
524			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
525				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
526					slog.String("error", cleanupErr.Error()))
527			}
528			return nil
529		}
530	
531		// Log file changes
532		logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)
533	
534		// Get git author
535		author, err := GetGitAuthor(ctx)
536		if err != nil {
537			return fmt.Errorf("failed to get git author: %w", err)
538		}
539	
540		// Get strategy and agent type
541		strat := GetStrategy(ctx)
542		agentType := ag.Type()
543	
544		// Get transcript position/identifier from pre-prompt state
545		var transcriptIdentifierAtStart string
546		var transcriptLinesAtStart int
547		if preState != nil {
548			transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
549			transcriptLinesAtStart = preState.TranscriptOffset
550		}
551	
552		// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
553		tokenUsage := agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)
554	
555		// Build fully-populated step context and delegate to strategy
556		stepCtx := strategy.StepContext{
557			SessionID:                sessionID,
558			ModifiedFiles:            relModifiedFiles,
559			NewFiles:                 relNewFiles,
560			DeletedFiles:             relDeletedFiles,
561			MetadataDir:              sessionDir,
562			MetadataDirAbs:           sessionDirAbs,
563			CommitMessage:            commitMessage,
564			TranscriptPath:           transcriptRef,
565			AuthorName:               author.Name,
566			AuthorEmail:              author.Email,
567			AgentType:                agentType,
568			StepTranscriptIdentifier: transcriptIdentifierAtStart,
569			StepTranscriptStart:      transcriptLinesAtStart,
570			TokenUsage:               tokenUsage,
571		}
572	
573		// Let agent contribute custom files to the checkpoint metadata
574		if contributor, ok := ag.(agent.CheckpointContributor); ok {
575			if err := contributor.ContributeCheckpointFiles(ctx, sessionID, sessionDirAbs); err != nil {
576				logging.Warn(logCtx, "agent checkpoint contribution failed",
577					slog.String("agent", string(agentType)),
578					slog.String("session_id", sessionID),
579					slog.String("error", err.Error()))
580			}
581		}
582	
583		if err := strat.SaveStep(ctx, stepCtx); err != nil {
584			return fmt.Errorf("failed to save step: %w", err)
585		}
586	
587		// Update session state with backfilled prompt after SaveStep.
588		// Done after SaveStep because SaveStep may reinitialize session state,
589		// which would overwrite an earlier LastPrompt update.
590		if backfilledPrompt != "" {
591			if state, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && state != nil && state.LastPrompt == "" {
592				state.LastPrompt = backfilledPrompt
593				if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
594					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
595						slog.String("error", saveErr.Error()))
596				}
597			}
598		}
599	
600		// Transition session phase and cleanup
601		transitionSessionTurnEnd(ctx, sessionID, event)
602		if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
603			logging.Warn(logCtx, "failed to cleanup pre-prompt state",
604				slog.String("error", cleanupErr.Error()))
605		}
606	
607		return nil
608	}
