610	// handleLifecycleCompaction handles context compaction: saves current progress
611	// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
612	// Also resets the transcript offset since the transcript may be truncated.
613	func handleLifecycleCompaction(ctx context.Context, ag agent.Agent, event *agent.Event) error {
614		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
615		logging.Info(logCtx, "compaction",
616			slog.String("event", event.Type.String()),
617			slog.String("session_id", event.SessionID),
618		)
619	
620		// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
621		sessionID := event.SessionID
622		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
623		if loadErr != nil {
624			logging.Warn(logCtx, "failed to load session state for compaction",
625				slog.String("error", loadErr.Error()))
626		}
627		if sessionState != nil {
628			persistEventMetadataToState(event, sessionState)
629	
630			if transErr := strategy.TransitionAndLog(ctx, sessionState, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
631				logging.Warn(logCtx, "compaction transition failed",
632					slog.String("error", transErr.Error()))
633			}
634	
635			if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
636				logging.Warn(logCtx, "failed to save session state after compaction",
637					slog.String("error", saveErr.Error()))
638			}
639		}
640	
641		logging.Info(logCtx, "context compaction detected")
642		return nil
643	}
644	
645	// handleLifecycleSessionEnd handles session end: marks the session as ended.
646	func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
647		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
648		logging.Info(logCtx, "session-end",
649			slog.String("event", event.Type.String()),
650			slog.String("session_id", event.SessionID),
651		)
652	
653		if event.SessionID == "" {
654			return nil // No session to update
655		}
656	
657		// Note: We intentionally don't clean up cached transcripts here.
658		// Post-session commits (carry-forward in ENDED phase) may still need
659		// the transcript to extract file changes. Cleanup is handled by
660		// `entire clean` or when the session state is fully removed.
661	
662		if err := markSessionEnded(ctx, event, event.SessionID); err != nil {
663			logging.Warn(logCtx, "failed to mark session ended",
664				slog.String("error", err.Error()))
665			// Don't attempt eager condense if we couldn't even mark the session ended —
666			// the session state may be in an inconsistent state.
667			return nil
668		}
669	
670		// Eagerly condense session data so PostCommit doesn't have to process it.
671		// This prevents zombie ENDED sessions from accumulating and causing O(N)
672		// overhead on every future commit (GitHub issue #591).
673		// Fail-open: if this fails, PostCommit will still process it on the next commit.
674		strat := GetStrategy(ctx)
675		if err := strat.CondenseAndMarkFullyCondensed(ctx, event.SessionID); err != nil {
676			logging.Warn(logCtx, "eager condense on session stop failed",
677				slog.String("session_id", event.SessionID),
678				slog.String("error", err.Error()))
679		}
680	
681		return nil
682	}
