689			slog.String("session_id", event.SessionID),
690			slog.String("tool_use_id", event.ToolUseID),
691			slog.String("transcript", event.SessionRef),
692		)
693	
694		// Capture pre-task state
695		if err := CapturePreTaskState(ctx, event.ToolUseID); err != nil {
696			return fmt.Errorf("failed to capture pre-task state: %w", err)
697		}
