702	// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
703	func handleLifecycleSubagentEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
704		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
705		if event.SubagentType == "" && event.TaskDescription == "" {
706			// Extract subagent type and description from tool input
707			event.SubagentType, event.TaskDescription = ParseSubagentTypeAndDescription(event.ToolInput)
708		}
709	
710		// Determine subagent transcript path
711		transcriptDir := filepath.Dir(event.SessionRef)
712		var subagentTranscriptPath string
713		if event.SubagentID != "" {
714			subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
715			if !fileExists(subagentTranscriptPath) {
716				subagentTranscriptPath = ""
717			}
718		}
719	
720		// Log context
721		subagentEndAttrs := []any{
722			slog.String("event", event.Type.String()),
723			slog.String("session_id", event.SessionID),
724			slog.String("tool_use_id", event.ToolUseID),
725		}
726		if event.SubagentID != "" {
727			subagentEndAttrs = append(subagentEndAttrs, slog.String("agent_id", event.SubagentID))
728		}
729		if subagentTranscriptPath != "" {
730			subagentEndAttrs = append(subagentEndAttrs, slog.String("subagent_transcript", subagentTranscriptPath))
731		}
732		logging.Info(logCtx, "subagent completed", subagentEndAttrs...)
733	
734		// Extract modified files from hook payload and/or subagent transcript
735		var modifiedFiles []string
736		modifiedFiles = append(modifiedFiles, event.ModifiedFiles...)
737		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
738			transcriptToScan := event.SessionRef
739			if subagentTranscriptPath != "" {
740				transcriptToScan = subagentTranscriptPath
741			}
742			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
743				logging.Warn(logCtx, "failed to extract modified files from subagent",
744					slog.String("error", fileErr.Error()))
745			} else {
746				modifiedFiles = mergeUnique(modifiedFiles, files)
747			}
748		}
749	
750		// Load pre-task state and detect file changes.
751		// If no pre-task state exists (agent doesn't support pre-task hook), fall back
752		// to the session's pre-prompt state. Without either, DetectFileChanges receives
753		// nil and treats ALL untracked files as new — which would create spurious task
754		// checkpoints for pre-existing untracked files (e.g., .github/hooks/entire.json).
755		preState, err := LoadPreTaskState(ctx, event.ToolUseID)
756		if err != nil {
757			logging.Warn(logCtx, "failed to load pre-task state",
758				slog.String("error", err.Error()))
759		}
760		var preUntrackedFiles []string
761		if preState != nil {
762			preUntrackedFiles = preState.PreUntrackedFiles()
763		}
764		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
765		if err != nil {
766			logging.Warn(logCtx, "failed to compute file changes",
767				slog.String("error", err.Error()))
768		}
769	
770		// Get worktree root and normalize paths
771		repoRoot, err := paths.WorktreeRoot(ctx)
772		if err != nil {
773			return fmt.Errorf("failed to get worktree root: %w", err)
774		}
775	
776		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
777		var relNewFiles, relDeletedFiles []string
778		if changes != nil {
779			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
780			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
781			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
782		}
783	
784		// If no changes, skip
785		if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
786			logging.Info(logCtx, "no file changes detected, skipping task checkpoint")
787			_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
788			return nil
789		}
790	
791		// Find checkpoint UUID from main transcript (best-effort)
792		var checkpointUUID string
793		// Use the existing CLI-level checkpoint UUID finder
794		mainLines, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
795		if mainLines != nil {
796			checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
797		}
798	
799		// Get git author
800		author, err := GetGitAuthor(ctx)
801		if err != nil {
802			return fmt.Errorf("failed to get git author: %w", err)
803		}
804	
805		// Build task checkpoint context
806		strat := GetStrategy(ctx)
807		agentType := ag.Type()
808	
809		taskStepCtx := strategy.TaskStepContext{
810			SessionID:              event.SessionID,
811			ToolUseID:              event.ToolUseID,
812			AgentID:                event.SubagentID,
813			ModifiedFiles:          relModifiedFiles,
814			NewFiles:               relNewFiles,
815			DeletedFiles:           relDeletedFiles,
816			TranscriptPath:         event.SessionRef,
817			SubagentTranscriptPath: subagentTranscriptPath,
818			CheckpointUUID:         checkpointUUID,
819			AuthorName:             author.Name,
820			AuthorEmail:            author.Email,
821			SubagentType:           event.SubagentType,
822			TaskDescription:        event.TaskDescription,
823			AgentType:              agentType,
824		}
825	
826		if err := strat.SaveTaskStep(ctx, taskStepCtx); err != nil {
827			return fmt.Errorf("failed to save task step: %w", err)
828		}
829	
830		_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
831		return nil
832	}
