836	// resolveTranscriptOffset determines the transcript offset to use for parsing.
837	// Prefers pre-prompt state, falls back to session state.
838	func resolveTranscriptOffset(ctx context.Context, preState *PrePromptState, sessionID string) int {
839		logCtx := logging.WithComponent(ctx, "lifecycle")
840		if preState != nil && preState.TranscriptOffset > 0 {
841			logging.Debug(logCtx, "pre-prompt state found, parsing transcript from offset",
842				slog.Int("offset", preState.TranscriptOffset))
843			return preState.TranscriptOffset
844		}
845	
846		// Fall back to session state
847		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
848		if loadErr != nil {
849			logging.Warn(logCtx, "failed to load session state",
850				slog.String("error", loadErr.Error()))
851			return 0
852		}
853		if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
854			logging.Debug(logCtx, "session state found, parsing transcript from offset",
855				slog.Int("offset", sessionState.CheckpointTranscriptStart))
856			return sessionState.CheckpointTranscriptStart
857		}
858	
859		return 0
860	}
