872	// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
873	func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event) {
874		logCtx := logging.WithComponent(ctx, "lifecycle")
875		turnState, loadErr := strategy.LoadSessionState(ctx, sessionID)
876		if loadErr != nil {
877			logging.Warn(logCtx, "failed to load session state for turn end",
878				slog.String("error", loadErr.Error()))
879			return
880		}
881		if turnState == nil {
882			return
883		}
884	
885		persistEventMetadataToState(event, turnState)
886	
887		if err := strategy.TransitionAndLog(ctx, turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
888			logging.Warn(logCtx, "turn-end transition failed",
889				slog.String("error", err.Error()))
890		}
891	
892		// Always dispatch to strategy for turn-end handling. The strategy reads
893		// work items from state (e.g. TurnCheckpointIDs), not the action list.
894		strat := GetStrategy(ctx)
895		if err := strat.HandleTurnEnd(ctx, turnState); err != nil {
896			logging.Warn(logCtx, "turn-end action dispatch failed",
897				slog.String("error", err.Error()))
898		}
899	
900		if updateErr := strategy.SaveSessionState(ctx, turnState); updateErr != nil {
901			logging.Warn(logCtx, "failed to update session phase on turn end",
902				slog.String("error", updateErr.Error()))
903		}
904	}
