906	// markSessionEnded transitions the session to ENDED phase via the state machine.
907	// If event is non-nil, hook-provided metrics are persisted to state before saving.
908	func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string) error {
909		state, err := strategy.LoadSessionState(ctx, sessionID)
910		if err != nil {
911			return fmt.Errorf("failed to load session state: %w", err)
912		}
913		if state == nil {
914			return nil // No state file, nothing to update
915		}
916	
917		if event != nil {
918			persistEventMetadataToState(event, state)
919		}
920	
921		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
922			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
923				slog.String("error", transErr.Error()))
924		}
925	
926		now := time.Now()
927		state.EndedAt = &now
928	
929		if err := strategy.SaveSessionState(ctx, state); err != nil {
930			return fmt.Errorf("failed to save session state: %w", err)
931		}
932		return nil
933	}
