944	func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) {
945		// Update ModelName if provided (model is known by turn-end even on first turn)
946		if event.Model != "" {
947			state.ModelName = event.Model
948		}
949	
950		// Persist hook-provided session metrics (e.g., from Cursor hooks)
951		if event.DurationMs > 0 {
952			state.SessionDurationMs = event.DurationMs
953		}
954		// Use hook-reported turn count if available (take max); otherwise
955		// increment on each TurnEnd event to count turns ourselves.
956		if event.TurnCount > 0 {
957			if event.TurnCount > state.SessionTurnCount {
958				state.SessionTurnCount = event.TurnCount
959			}
960		} else if event.Type == agent.TurnEnd {
961			state.SessionTurnCount++
962		}
963		if event.ContextTokens > 0 {
964			state.ContextTokens = event.ContextTokens
965		}
966		if event.ContextWindowSize > 0 {
967			state.ContextWindowSize = event.ContextWindowSize
968		}
969	}
