40	// GetRewindPoints returns available rewind points.
41	// Uses checkpoint.GitStore.ListTemporaryCheckpoints for reading from shadow branches.
42	func (s *ManualCommitStrategy) GetRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
43		repo, err := OpenRepository(ctx)
44		if err != nil {
45			return nil, fmt.Errorf("failed to open git repository: %w", err)
46		}
47	
48		// Get checkpoint store
49		store, err := s.getCheckpointStore()
50		if err != nil {
51			return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
52		}
53	
54		// Get current HEAD to find matching shadow branch
55		head, err := repo.Head()
56		if err != nil {
57			return nil, fmt.Errorf("failed to get HEAD: %w", err)
58		}
59	
60		// Find sessions for current HEAD
61		sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
62		if err != nil {
63			// Log error but continue to check for logs-only points
64			sessions = nil
65		}
66	
67		var allPoints []RewindPoint
68	
69		// Collect checkpoint points from active sessions using checkpoint.GitStore
70		// Cache session prompts by session ID to avoid re-reading the same prompt file
71		sessionPrompts := make(map[string]string)
72	
73		for _, state := range sessions {
74			checkpoints, err := store.ListTemporaryCheckpoints(ctx, state.BaseCommit, state.WorktreeID, state.SessionID, limit)
75			if err != nil {
76				continue // Error reading checkpoints, skip this session
77			}
78	
79			for _, cp := range checkpoints {
80				// Get session prompt (cached by session ID)
81				sessionPrompt, ok := sessionPrompts[cp.SessionID]
82				if !ok {
83					sessionPrompt = readSessionPrompt(repo, cp.CommitHash, cp.MetadataDir)
84					sessionPrompts[cp.SessionID] = sessionPrompt
85				}
86	
87				allPoints = append(allPoints, RewindPoint{
88					ID:               cp.CommitHash.String(),
89					Message:          cp.Message,
90					MetadataDir:      cp.MetadataDir,
91					Date:             cp.Timestamp,
92					IsTaskCheckpoint: cp.IsTaskCheckpoint,
93					ToolUseID:        cp.ToolUseID,
94					SessionID:        cp.SessionID,
95					SessionPrompt:    sessionPrompt,
96					Agent:            state.AgentType,
97				})
98			}
99		}
100	
101		// Sort by date, most recent first
102		sort.Slice(allPoints, func(i, j int) bool {
103			return allPoints[i].Date.After(allPoints[j].Date)
104		})
105	
106		if len(allPoints) > limit {
107			allPoints = allPoints[:limit]
108		}
109	
110		// Also include logs-only points from commit history
111		logsOnlyPoints, err := s.GetLogsOnlyRewindPoints(ctx, limit)
112		if err == nil && len(logsOnlyPoints) > 0 {
113			// Build set of existing point IDs for deduplication
114			existingIDs := make(map[string]bool)
115			for _, p := range allPoints {
116				existingIDs[p.ID] = true
117			}
118	
119			// Add logs-only points that aren't already in the list
120			for _, p := range logsOnlyPoints {
121				if !existingIDs[p.ID] {
122					allPoints = append(allPoints, p)
123				}
124			}
125	
126			// Re-sort by date
127			sort.Slice(allPoints, func(i, j int) bool {
128				return allPoints[i].Date.After(allPoints[j].Date)
129			})
130	
131			// Re-trim to limit
132			if len(allPoints) > limit {
133				allPoints = allPoints[:limit]
134			}
135		}
136	
137		return allPoints, nil
138	}
