140	// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
141	// condensed session logs on the entire/checkpoints/v1 branch. These are commits that
142	// were created with session data but the shadow branch has been condensed.
143	//
144	// The function works by:
145	// 1. Getting all checkpoints from the entire/checkpoints/v1 branch
146	// 2. Building a map of checkpoint ID -> checkpoint info
147	// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
148	// 4. Matching by checkpoint ID (stable across amend/rebase)
149	func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
150		repo, err := OpenRepository(ctx)
151		if err != nil {
152			return nil, err
153		}
154	
155		// Get all checkpoints from entire/checkpoints/v1 branch
156		checkpoints, err := s.listCheckpoints(ctx)
157		if err != nil {
158			// No checkpoints yet is fine
159			return nil, nil //nolint:nilerr // Expected when no checkpoints exist
160		}
161	
162		if len(checkpoints) == 0 {
163			return nil, nil
164		}
165	
166		// Build map of checkpoint ID -> checkpoint info
167		// Checkpoint ID is the stable link from Entire-Checkpoint trailer
168		checkpointInfoMap := make(map[id.CheckpointID]CheckpointInfo)
169		for _, cp := range checkpoints {
170			if !cp.CheckpointID.IsEmpty() {
171				checkpointInfoMap[cp.CheckpointID] = cp
172			}
173		}
174	
175		// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
176		metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts
177	
178		head, err := repo.Head()
179		if err != nil {
180			return nil, fmt.Errorf("failed to get HEAD: %w", err)
181		}
182	
183		// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
184		iter, err := repo.Log(&git.LogOptions{
185			From:  head.Hash(),
186			Order: git.LogOrderCommitterTime,
187		})
188		if err != nil {
189			return nil, fmt.Errorf("failed to get commit log: %w", err)
190		}
191	
192		var points []RewindPoint
193		count := 0
194	
195		err = iter.ForEach(func(c *object.Commit) error {
196			if err := ctx.Err(); err != nil {
197				return err //nolint:wrapcheck // Propagating context cancellation
198			}
199			if count >= logsOnlyScanLimit {
200				return errStop
201			}
202			count++
203	
204			// Extract all checkpoint IDs from Entire-Checkpoint trailers.
205			// Squash merge commits may contain multiple trailers from the original commits.
206			allCpIDs := trailers.ParseAllCheckpoints(c.Message)
207			if len(allCpIDs) == 0 {
208				return nil
209			}
210	
211			// Resolve to the latest checkpoint by creation time (consistent with `entire resume`).
212			cpInfo, found := ResolveLatestCheckpointFromMap(allCpIDs, checkpointInfoMap)
213			if !found {
214				return nil
215			}
216	
217			// Create logs-only rewind point
218			message := strings.Split(c.Message, "\n")[0]
219	
220			// Read session prompts from metadata tree
221			var sessionPrompt string
222			var sessionPrompts []string
223			if metadataTree != nil {
224				checkpointPath := paths.CheckpointPath(cpInfo.CheckpointID) //nolint:staticcheck // already present in codebase
225				// For multi-session checkpoints, read all prompts
226				if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
227					sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
228					// Use the last (most recent) prompt as the main session prompt
229					if len(sessionPrompts) > 0 {
230						sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
231					}
232				} else {
233					sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
234					if sessionPrompt != "" {
235						sessionPrompts = []string{sessionPrompt}
236					}
237				}
238			}
239	
240			points = append(points, RewindPoint{
241				ID:             c.Hash.String(),
242				Message:        message,
243				Date:           c.Author.When,
244				IsLogsOnly:     true,
245				CheckpointID:   cpInfo.CheckpointID,
246				Agent:          cpInfo.Agent,
247				SessionID:      cpInfo.SessionID,
248				SessionPrompt:  sessionPrompt,
249				SessionCount:   cpInfo.SessionCount,
250				SessionIDs:     cpInfo.SessionIDs,
251				SessionPrompts: sessionPrompts,
252			})
253	
254			return nil
255		})
256	
257		if err != nil && !errors.Is(err, errStop) {
258			return nil, fmt.Errorf("error iterating commits: %w", err)
259		}
260	
261		if len(points) > limit {
262			points = points[:limit]
263		}
264	
265		return points, nil
266	}
267	
268	// ResolveLatestCheckpointFromMap picks the checkpoint with the latest CreatedAt
269	// from a list of checkpoint IDs. Filters to IDs present in infoMap, then picks
270	// the one with the most recent CreatedAt.
271	func ResolveLatestCheckpointFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo) (CheckpointInfo, bool) {
272		var found bool
273		var latest CheckpointInfo
274		for _, cpID := range cpIDs {
275			info, ok := infoMap[cpID]
276			if !ok {
277				continue
278			}
279			if !found || info.CreatedAt.After(latest.CreatedAt) {
280				latest = info
281				found = true
282			}
283		}
284		return latest, found
285	}
