471	// restoreAgentCheckpointFiles extracts agent-contributed files from the
472	// checkpoint tree and hands them to the agent's CheckpointRestorer (if any).
473	// Best-effort: errors are logged but do not fail the rewind.
474	func restoreAgentCheckpointFiles(ctx context.Context, errW io.Writer, tree *object.Tree, sessionID string) {
475		ag, err := agentForSession(ctx, sessionID)
476		if err != nil || ag == nil {
477			return
478		}
479		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
480		extras := extractExtraFilesFromTree(tree, metadataDir)
481		runCheckpointRestorer(ctx, errW, ag, sessionID, extras)
482	}
