484	// runCheckpointRestorer invokes a CheckpointRestorer if the agent implements it
485	// and there is anything to restore. Errors are non-fatal.
486	func runCheckpointRestorer(ctx context.Context, errW io.Writer, ag agent.Agent, sessionID string, files map[string][]byte) {
487		if len(files) == 0 {
488			return
489		}
490		restorer, ok := ag.(agent.CheckpointRestorer)
491		if !ok {
492			return
493		}
494		if err := restorer.RestoreCheckpointFiles(ctx, sessionID, files); err != nil {
495			fmt.Fprintf(errW, "[entire] Warning: agent checkpoint restore failed: %v\n", err)
496		}
497	}
