499	// agentForSession resolves the agent registered for a session by loading its
500	// state and looking up the agent type in the registry. Returns (nil, nil)
501	// when the session has no recorded agent or no state exists.
502	func agentForSession(ctx context.Context, sessionID string) (agent.Agent, error) {
503		state, err := LoadSessionState(ctx, sessionID)
504		if err != nil {
505			return nil, fmt.Errorf("load session state: %w", err)
506		}
507		if state == nil || state.AgentType == "" {
508			return nil, nil //nolint:nilnil // "no agent resolvable" is the happy no-op
509		}
510		return ResolveAgentForRewind(state.AgentType)
511	}
