513	// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
514	// This ensures that when the user commits after rewinding, the next checkpoint will only
515	// include prompts from the rewound point, not prompts from later checkpoints.
516	func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
517		// Extract session ID from the checkpoint commit's Entire-Session trailer
518		sessionID, found := trailers.ParseSession(commit.Message)
519		if !found {
520			return errors.New("checkpoint has no Entire-Session trailer")
521		}
522	
523		// Load session state to get the shadow branch name
524		state, err := s.loadSessionState(ctx, sessionID)
525		if err != nil {
526			return fmt.Errorf("failed to load session state: %w", err)
527		}
528		if state == nil {
529			return fmt.Errorf("session %s not found", sessionID)
530		}
531	
532		// Reset the shadow branch to the checkpoint commit
533		shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
534		refName := plumbing.NewBranchReferenceName(shadowBranchName)
535	
536		// Update the reference to point to the checkpoint commit
537		ref := plumbing.NewHashReference(refName, commit.Hash)
538		if err := repo.Storer.SetReference(ref); err != nil {
539			return fmt.Errorf("failed to update shadow branch: %w", err)
540		}
541	
542		fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
543		return nil
544	}
