554	// PreviewRewind returns what will happen if rewinding to the given point.
555	// This allows showing warnings about untracked files that will be deleted.
556	func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
557		// Logs-only points don't modify the working directory
558		if point.IsLogsOnly {
559			return &RewindPreview{}, nil
560		}
561	
562		repo, err := OpenRepository(ctx)
563		if err != nil {
564			return nil, fmt.Errorf("failed to open git repository: %w", err)
565		}
566	
567		// Get the checkpoint commit
568		commitHash := plumbing.NewHash(point.ID)
569		commit, err := repo.CommitObject(commitHash)
570		if err != nil {
571			return nil, fmt.Errorf("failed to get commit: %w", err)
572		}
573	
574		tree, err := commit.Tree()
575		if err != nil {
576			return nil, fmt.Errorf("failed to get tree: %w", err)
577		}
578	
579		// Load session state to get untracked files that existed at session start
580		sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
581		var preservedUntrackedFiles map[string]bool
582		if hasSessionTrailer {
583			state, stateErr := s.loadSessionState(ctx, sessionID)
584			if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
585				preservedUntrackedFiles = make(map[string]bool)
586				for _, f := range state.UntrackedFilesAtStart {
587					preservedUntrackedFiles[f] = true
588				}
589			}
590		}
591	
592		// Build set of files in the checkpoint tree (excluding metadata)
593		checkpointFiles := make(map[string]bool)
594		var filesToRestore []string
595		err = tree.Files().ForEach(func(f *object.File) error {
596			if err := ctx.Err(); err != nil {
597				return err //nolint:wrapcheck // Propagating context cancellation
598			}
599			if !strings.HasPrefix(f.Name, entireDir) {
600				checkpointFiles[f.Name] = true
601				filesToRestore = append(filesToRestore, f.Name)
602			}
603			return nil
604		})
605		if err != nil {
606			return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
607		}
608	
609		// Get HEAD tree to identify tracked files
610		head, err := repo.Head()
611		if err != nil {
612			return nil, fmt.Errorf("failed to get HEAD: %w", err)
613		}
614		headCommit, err := repo.CommitObject(head.Hash())
615		if err != nil {
616			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
617		}
618		headTree, err := headCommit.Tree()
619		if err != nil {
620			return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
621		}
622	
623		// Build set of files tracked in HEAD
624		trackedFiles := make(map[string]bool)
625		//nolint:errcheck // Error is not critical for preview
626		_ = headTree.Files().ForEach(func(f *object.File) error {
627			if err := ctx.Err(); err != nil {
628				return err //nolint:wrapcheck // Propagating context cancellation
629			}
630			trackedFiles[f.Name] = true
631			return nil
632		})
633	
634		// Find untracked files that would be deleted.
635		// Uses git ls-files to only consider non-ignored files.
636		var filesToDelete []string
637		untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
638		if untrackedErr != nil {
639			fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
640			return &RewindPreview{
641				FilesToRestore: filesToRestore,
642				FilesToDelete:  filesToDelete,
643			}, nil
644		}
645		for _, relPath := range untrackedNow {
646			if checkpointFiles[relPath] {
647				continue
648			}
649			if trackedFiles[relPath] {
650				continue
651			}
652			if preservedUntrackedFiles[relPath] {
653				continue
654			}
655			filesToDelete = append(filesToDelete, relPath)
656		}
657	
658		// Sort for consistent output
659		sort.Strings(filesToRestore)
660		sort.Strings(filesToDelete)
661	
662		return &RewindPreview{
663			FilesToRestore: filesToRestore,
664			FilesToDelete:  filesToDelete,
665		}, nil
666	}
