668	// RestoreLogsOnly restores session logs from a logs-only rewind point.
669	// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
670	// Does not modify the working directory.
671	// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
672	// If force is false, prompts for confirmation when local logs have newer timestamps.
673	// Returns info about each restored session so callers can print correct per-session resume commands.
674	func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, w, errW io.Writer, point RewindPoint, force bool) ([]RestoredSession, error) {
675		if !point.IsLogsOnly {
676			return nil, errors.New("not a logs-only rewind point")
677		}
678	
679		if point.CheckpointID.IsEmpty() {
680			return nil, errors.New("missing checkpoint ID")
681		}
682	
683		// Resolve which store has this checkpoint. Try v2 first when enabled.
684		// The chosen reader is used for all subsequent reads (summary + session content)
685		// to avoid mixed v1/v2 reads. No per-session fallback to v1: during dual-write,
686		// both stores receive the same data, so if v2 has the summary it also has the
687		// transcripts on /full/* refs.
688		var reader committedReader
689		var summary *cpkg.CheckpointSummary
690	
691		if settings.IsCheckpointsV2Enabled(ctx) {
692			v2Store, v2Err := s.getV2CheckpointStore(ctx)
693			if v2Err == nil {
694				v2Summary, readErr := v2Store.ReadCommitted(ctx, point.CheckpointID)
695				if readErr != nil {
696					logging.Debug(ctx, "v2 ReadCommitted failed, falling back to v1",
697						slog.String("checkpoint_id", string(point.CheckpointID)),
698						slog.String("error", readErr.Error()),
699					)
700				} else if v2Summary != nil {
701					reader = v2Store
702					summary = v2Summary
703				}
704			}
705		}
706	
707		if summary == nil {
708			v1Store, err := s.getCheckpointStore()
709			if err != nil {
710				return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
711			}
712			summary, err = v1Store.ReadCommitted(ctx, point.CheckpointID)
713			if err != nil {
714				return nil, fmt.Errorf("failed to read checkpoint: %w", err)
715			}
716			reader = v1Store
717		}
718		if summary == nil {
719			return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
720		}
721	
722		// Get worktree root for agent session directory lookup
723		repoRoot, err := paths.WorktreeRoot(ctx)
724		if err != nil {
725			return nil, fmt.Errorf("failed to get worktree root: %w", err)
726		}
727	
728		// Check for newer local logs if not forcing
729		if !force {
730			sessions := s.classifySessionsForRestore(ctx, repoRoot, reader, point.CheckpointID, summary)
731			hasConflicts := false
732			for _, sess := range sessions {
733				if sess.Status == StatusLocalNewer {
734					hasConflicts = true
735					break
736				}
737			}
738			if hasConflicts {
739				shouldOverwrite, promptErr := PromptOverwriteNewerLogs(errW, sessions)
740				if promptErr != nil {
741					return nil, promptErr
742				}
743				if !shouldOverwrite {
744					fmt.Fprintf(w, "Resume cancelled. Local session logs preserved.\n")
745					return nil, nil
746				}
747			}
748		}
749	
750		// Count sessions to restore
751		totalSessions := len(summary.Sessions)
752		if totalSessions > 1 {
753			fmt.Fprintf(w, "Restoring %d sessions from checkpoint:\n", totalSessions)
754		}
755	
756		// Restore all sessions (oldest to newest, using 0-based indexing)
757		var restored []RestoredSession
758		for i := range totalSessions {
759			content, readErr := reader.ReadSessionContent(ctx, point.CheckpointID, i)
760			if readErr != nil {
761				if !errors.Is(readErr, cpkg.ErrNoTranscript) {
762					fmt.Fprintf(errW, "  Warning: failed to read session %d: %v\n", i, readErr)
763				}
764				continue
765			}
766			if content == nil || len(content.Transcript) == 0 {
767				continue
768			}
769	
770			sessionID := content.Metadata.SessionID
771			if sessionID == "" {
772				fmt.Fprintf(errW, "  Warning: session %d has no session ID, skipping\n", i)
773				continue
774			}
775	
776			// Resolve per-session agent from metadata — skip if agent is unknown
777			if content.Metadata.Agent == "" {
778				fmt.Fprintf(errW, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
779				continue
780			}
781			sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
782			if agErr != nil {
783				fmt.Fprintf(errW, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
784				continue
785			}
786	
787			// Compute transcript path from current repo location for cross-machine portability.
788			sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
789			if dirErr != nil {
790				fmt.Fprintf(errW, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
791				continue
792			}
793			sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
794			if resolver, ok := sessionAgent.(agent.RestoredSessionPathResolver); ok {
795				resolvedFile, resolveErr := resolver.ResolveRestoredSessionFile(sessionAgentDir, sessionID, content.Transcript)
796				if resolveErr != nil {
797					fmt.Fprintf(errW, "  Warning: failed to resolve restored session path for session %d (%s): %v (using fallback path)\n", i, sessionID, resolveErr)
798				} else {
799					sessionFile = resolvedFile
800				}
801			}
802	
803			// Get first prompt for display
804			promptPreview := ExtractFirstPrompt(content.Prompts)
805	
806			if totalSessions > 1 {
807				isLatest := i == totalSessions-1
808				if promptPreview != "" {
809					if isLatest {
810						fmt.Fprintf(w, "  Session %d (latest): %s\n", i+1, promptPreview)
811					} else {
812						fmt.Fprintf(w, "  Session %d: %s\n", i+1, promptPreview)
813					}
814				}
815				fmt.Fprintf(w, "    Writing to: %s\n", sessionFile)
816			} else {
817				fmt.Fprintf(w, "Writing transcript to: %s\n", sessionFile)
818			}
819	
820			// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
821			if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
822				fmt.Fprintf(errW, "    Warning: failed to create directory: %v\n", mkdirErr)
823				continue
824			}
825	
826			agentSession := &agent.AgentSession{
827				SessionID:  sessionID,
828				AgentName:  sessionAgent.Name(),
829				RepoPath:   repoRoot,
830				SessionRef: sessionFile,
831				NativeData: content.Transcript,
832			}
833			if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
834				if totalSessions > 1 {
835					fmt.Fprintf(errW, "    Warning: failed to write session: %v\n", writeErr)
836					continue
837				}
838				return nil, fmt.Errorf("failed to write session: %w", writeErr)
839			}
840	
841			// Hand any agent-contributed extras (e.g., Cursor chat archives) back
842			// to the agent for restoration to native storage. Best-effort.
843			runCheckpointRestorer(ctx, errW, sessionAgent, sessionID, content.ExtraFiles)
844	
845			restored = append(restored, RestoredSession{
846				SessionID: sessionID,
847				Agent:     sessionAgent.Type(),
848				Prompt:    promptPreview,
849				CreatedAt: content.Metadata.CreatedAt,
850			})
851		}
852	
853		return restored, nil
854	}
