865	// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
866	// Returns an empty string if the prompt cannot be read.
867	func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
868		// Get the commit and its tree
869		commit, err := repo.CommitObject(commitHash)
870		if err != nil {
871			return ""
872		}
873	
874		tree, err := commit.Tree()
875		if err != nil {
876			return ""
877		}
878	
879		// Look for prompt.txt in the metadata directory
880		promptPath := metadataDir + "/" + paths.PromptFileName
881		promptEntry, err := tree.File(promptPath)
882		if err != nil {
883			return ""
884		}
885	
886		content, err := promptEntry.Contents()
887		if err != nil {
888			return ""
889		}
890	
891		return ExtractFirstPrompt(content)
