894	// SessionRestoreStatus represents the status of a session being restored.
895	type SessionRestoreStatus int
896	
897	const (
898		StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
899		StatusUnchanged                                   // Local and checkpoint are the same
900		StatusCheckpointNewer                             // Checkpoint has newer entries
901		StatusLocalNewer                                  // Local has newer entries (conflict)
902	)
903	
904	// SessionRestoreInfo contains information about a session being restored.
905	type SessionRestoreInfo struct {
906		SessionID      string
907		Prompt         string               // First prompt preview for display
908		Status         SessionRestoreStatus // Status of this session
909		LocalTime      time.Time
910		CheckpointTime time.Time
911	}
912	
913	// classifySessionsForRestore checks all sessions in a checkpoint and returns info
914	// about each session, including whether local logs have newer timestamps.
915	// repoRoot is used to compute per-session agent directories.
916	// Sessions without agent metadata are skipped (cannot determine target directory).
917	func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store committedReader, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
918		var sessions []SessionRestoreInfo
919	
920		totalSessions := len(summary.Sessions)
921		// Check all sessions (0-based indexing)
922		for i := range totalSessions {
923			content, err := store.ReadSessionContent(ctx, checkpointID, i)
924			if err != nil || content == nil || len(content.Transcript) == 0 {
925				continue
926			}
927	
928			sessionID := content.Metadata.SessionID
929			if sessionID == "" || content.Metadata.Agent == "" {
930				continue
931			}
932	
933			sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
934			if agErr != nil {
935				continue
936			}
937	
938			// Compute transcript path from current repo location for cross-machine portability.
939			sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
940			if dirErr != nil {
941				continue
942			}
943			localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
944	
945			localTime := paths.GetLastTimestampFromFile(localPath)
946			checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
947			status := ClassifyTimestamps(localTime, checkpointTime)
948	
949			sessions = append(sessions, SessionRestoreInfo{
950				SessionID:      sessionID,
951				Prompt:         ExtractFirstPrompt(content.Prompts),
952				Status:         status,
953				LocalTime:      localTime,
954				CheckpointTime: checkpointTime,
955			})
956		}
957	
958		return sessions
959	}
960	
961	// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
962	func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
963		// Local file doesn't exist (no timestamp found)
964		if localTime.IsZero() {
965			return StatusNew
966		}
967	
968		// Can't determine checkpoint time - treat as new/safe
969		if checkpointTime.IsZero() {
970			return StatusNew
971		}
972	
973		// Compare timestamps
974		if localTime.After(checkpointTime) {
975			return StatusLocalNewer
976		}
977		if checkpointTime.After(localTime) {
978			return StatusCheckpointNewer
979		}
980		return StatusUnchanged
981	}
982	
983	// StatusToText returns a human-readable status string.
984	func StatusToText(status SessionRestoreStatus) string {
985		switch status {
986		case StatusNew:
987			return "(new)"
988		case StatusUnchanged:
989			return "(unchanged)"
990		case StatusCheckpointNewer:
991			return "(checkpoint is newer)"
992		case StatusLocalNewer:
993			return "(local is newer)" // shouldn't appear in non-conflict list
994		default:
995			return ""
996		}
997	}
998	
999	// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
1000	// session logs that have newer timestamps than the checkpoint versions.
1001	func PromptOverwriteNewerLogs(errW io.Writer, sessions []SessionRestoreInfo) (bool, error) {
1002		if !interactive.CanPromptInteractively() {
1003			return false, errors.New("cannot prompt to overwrite local session logs in non-interactive mode; rerun with --force to overwrite or use a TTY to confirm")
1004		}
1005	
1006		// Separate conflicting and non-conflicting sessions
1007		var conflicting, nonConflicting []SessionRestoreInfo
1008		for _, s := range sessions {
1009			if s.Status == StatusLocalNewer {
1010				conflicting = append(conflicting, s)
1011			} else {
1012				nonConflicting = append(nonConflicting, s)
1013			}
1014		}
1015	
1016		fmt.Fprintf(errW, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
1017		for _, info := range conflicting {
1018			// Show prompt if available, otherwise fall back to session ID
1019			if info.Prompt != "" {
1020				fmt.Fprintf(errW, "  \"%s\"\n", info.Prompt)
