1124		}
1125		metadataDirAbs := filepath.Join(worktreeRoot, paths.SessionMetadataDirFromSessionID(sessionID))
1126		if mkErr := os.MkdirAll(metadataDirAbs, 0o750); mkErr != nil {
1127			return map[string][]byte{}, fmt.Errorf("ensure metadata dir: %w", mkErr)
1128		}
1129	
