1140				logging.Debug(logging.WithComponent(ctx, "checkpoint"), "live extras contributor failed",
1141					slog.String("session_id", sessionID),
1142					slog.String("agent", string(name)),
1143					slog.String("error", err.Error()),
1144				)
1145			}
1146		}
