1148		entries, err := os.ReadDir(metadataDirAbs)
1149		if err != nil {
1150			return map[string][]byte{}, fmt.Errorf("read metadata dir: %w", err)
1151		}
1152		extras := map[string][]byte{}
1153		for _, e := range entries {
