1178	// extractExtraFilesFromTree walks the shadow branch tree under metadataDir and
1179	// returns any files that are not part of the standard metadata set. These are
1180	// agent-contributed files (e.g., .cursor-chat.json archives).
1181	func extractExtraFilesFromTree(tree *object.Tree, metadataDir string) map[string][]byte {
1182		prefix := metadataDir + "/"
1183		extras := make(map[string][]byte)
1184	
1185		_ = tree.Files().ForEach(func(f *object.File) error { //nolint:errcheck // best-effort: extra files are optional
1186			if !strings.HasPrefix(f.Name, prefix) {
1187				return nil
1188			}
1189			relPath := strings.TrimPrefix(f.Name, prefix)
1190			// Skip subdirectories (tasks/) and standard files
1191			if strings.Contains(relPath, "/") {
1192				return nil
1193			}
1194			if standardMetadataFiles[relPath] {
1195				return nil
1196			}
1197			// Read via Reader, not Contents(): Contents() returns string, which loses
1198			// raw bytes for any non-UTF8 file. ExtraFiles is typed as []byte so we
1199			// stream the blob through io.ReadAll to preserve exact bytes.
1200			reader, err := f.Reader()
1201			if err != nil {
1202				return nil //nolint:nilerr // best-effort: skip files we can't read
1203			}
1204			content, err := io.ReadAll(reader)
1205			_ = reader.Close()
1206			if err != nil {
1207				return nil //nolint:nilerr // best-effort: skip files we can't read
1208			}
1209			extras[relPath] = content
1210			return nil
1211		})
1212	
1213		if len(extras) == 0 {
1214			return nil
1215		}
1216		return extras
1217	}
