39	
40		if _, err := db.ExecContext(context.Background(),`
41			CREATE TABLE meta  (key TEXT PRIMARY KEY, value TEXT);
42			CREATE TABLE blobs (id  TEXT PRIMARY KEY, data BLOB);
43		`); err != nil {
44			t.Fatalf("create tables: %v", err)
45		}
46		if metaValue != nil {
