63	// parseArchiveLines reads the JSONL export and splits it into meta + blob rows.
64	func parseArchiveLines(t *testing.T, data []byte) (metas []jsonlLine, blobs []jsonlLine) {
65		t.Helper()
66		scanner := bufio.NewScanner(bytes.NewReader(data))
67		scanner.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
68		for scanner.Scan() {
69			var l jsonlLine
70			if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
71				t.Fatalf("unmarshal line %q: %v", scanner.Text(), err)
72			}
73			switch l.T {
74			case "meta":
75				metas = append(metas, l)
76			case "blob":
77				blobs = append(blobs, l)
78			default:
79				t.Fatalf("unexpected row type %q", l.T)
80			}
81		}
82		if err := scanner.Err(); err != nil {
83			t.Fatalf("scan: %v", err)
84		}
85		return metas, blobs
86	}
