93		metaJSON := []byte(`{"agentId":"11111111-2222-3333-4444-555555555555","latestRootBlobId":"aaa","name":"Test"}`)
94		blobBytes := map[string][]byte{
95			"aaa111": []byte(`{"role":"user","content":"hello"}`),
96			"bbb222": []byte(`{"role":"assistant","content":"hi"}`),
97		}
