106		if len(metas) != 1 {
107			t.Fatalf("meta rows = %d, want 1", len(metas))
108		}
109		if metas[0].K != "0" {
110			t.Errorf("meta.key = %q, want %q", metas[0].K, "0")
111		}
112		if !json.Valid(metas[0].V) {
113			t.Errorf("meta.v is not valid JSON: %s", metas[0].V)
114		}
115		if !bytes.Equal([]byte(metas[0].V), metaJSON) {
116			t.Errorf("meta.v = %s, want %s", metas[0].V, metaJSON)
117		}
118		if len(blobs) != len(blobBytes) {
119			t.Fatalf("blob rows = %d, want %d", len(blobs), len(blobBytes))
120		}
121		for _, b := range blobs {
122			want, ok := blobBytes[b.ID]
123			if !ok {
124				t.Errorf("unexpected blob id %q", b.ID)
125				continue
126			}
127			got, err := base64.StdEncoding.DecodeString(b.Data)
128			if err != nil {
129				t.Errorf("decode blob %s: %v", b.ID, err)
130				continue
131			}
132			// Cursor chat-message blobs go through secret redaction, which round-trips
133			// the JSON via Marshal and may reorder keys. Compare structurally instead
134			// of byte-equal.
135			var gotDoc, wantDoc any
136			if uerr := json.Unmarshal(got, &gotDoc); uerr != nil {
137				t.Errorf("blob %s decoded bytes are not JSON: %v", b.ID, uerr)
138				continue
139			}
140			if uerr := json.Unmarshal(want, &wantDoc); uerr != nil {
141				t.Errorf("blob %s seed bytes are not JSON: %v", b.ID, uerr)
142				continue
143			}
144			if !reflect.DeepEqual(gotDoc, wantDoc) {
145				t.Errorf("blob %s roundtrip mismatch:\n got:  %s\n want: %s", b.ID, got, want)
146			}
147		}
148	}
