150	func TestExportChatArchive_RedactsBlobContent(t *testing.T) {
151		// Cursor chat blobs may carry user-pasted secrets in their content fields.
152		// The export pipeline must run them through the same redactor the main
153		// transcript uses; cursor.go's redactBlobData targets {role, content} JSON
154		// shapes (string and array variants) and leaves merkle tree nodes alone.
155		tmp := t.TempDir()
156		t.Setenv("HOME", tmp)
157	
158		// High-entropy token shaped like a typical OpenAI/Anthropic API key — the
159		// AKIA-style AWS test key has too little entropy to trip the threshold.
160		secret := "REDACTED"
161		stringContent := []byte(`{"role":"user","content":"key=` + secret + `"}`)
162		arrayContent := []byte(`{"role":"assistant","content":[{"type":"text","text":"token: ` + secret + `"}]}`)
163		// Tool-use shape: secret hides inside a nested input object. A top-level-only
164		// redactor would miss this — recursive walk must catch it.
165		toolUseContent := []byte(`{"role":"assistant","content":[{"type":"tool_use","name":"Write","input":{"path":"foo.txt","contents":"# api: ` + secret + `"}}]}`)
166		// Cursor-wrapped binary frame: real cursor DBs put user prompts inside a
167		// protobuf-like envelope. The bytes aren't JSON but the secret is in the
168		// clear. Falls through to redact.Bytes byte-level scrubbing.
169		wrappedFrame := append([]byte{0x0a, 0x8a, 0x01}, []byte("user input: "+secret+" trailing")...)
170		treeNode := []byte(`{"latestRootBlobId":"958e728654e1e5e7b019e874d9045f53ba89b36af97e785f023ea8963e961c45"}`)
171	
172		seedStoreDB(t, tmp, []byte(`{"agentId":"x"}`), map[string][]byte{
173			"chat-string":     stringContent,
174			"chat-array":      arrayContent,
175			"chat-tool-use":   toolUseContent,
176			"wrapped-binary":  wrappedFrame,
177			"tree-node":       treeNode,
178		})
179	
180		data, err := ExportChatArchive(context.Background(), testAgentID)
181		if err != nil {
182			t.Fatalf("ExportChatArchive: %v", err)
183		}
184		_, blobs := parseArchiveLines(t, data)
185	
186		for _, b := range blobs {
187			raw, err := base64.StdEncoding.DecodeString(b.Data)
188			if err != nil {
189				t.Fatalf("decode %s: %v", b.ID, err)
190			}
191			if b.ID == "tree-node" {
192				if !bytes.Equal(raw, treeNode) {
193					t.Errorf("tree node bytes mutated by redaction:\n got:  %s\n want: %s", raw, treeNode)
194				}
195				continue
196			}
197			if bytes.Contains(raw, []byte(secret)) {
198				t.Errorf("blob %s leaked secret %q after redaction:\n%s", b.ID, secret, raw)
199			}
200			if !bytes.Contains(raw, []byte("REDACTED")) {
