1827	// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1828	// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1829	func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1830		info, err := os.Stat(filePath)
1831		if err != nil {
1832			return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1833		}
1834	
1835		mode := filemode.Regular
1836		if info.Mode()&0o111 != 0 {
1837			mode = filemode.Executable
1838		}
1839	
1840		content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1841		if err != nil {
1842			return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1843		}
1844	
1845		// Skip redaction for binary files — they can't contain text secrets and
1846		// running string replacement on them would corrupt the data.
1847		// Also skip for opaque agent-contributed archives: they wrap binary blobs
1848		// (e.g. SQLite files) as base64 inside JSON, so IsBinary would classify
1849		// them as text, but redaction on the base64 substrings corrupts the data.
1850		isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1851		if binErr != nil || isBin || isOpaqueAgentArchive(treePath) {
1852			hash, err := CreateBlobFromContent(repo, content)
1853			if err != nil {
1854				return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1855			}
1856			return hash, mode, nil
1857		}
1858	
1859		if strings.HasSuffix(treePath, ".jsonl") {
1860			redacted, jsonlErr := redact.JSONLBytes(content)
1861			if jsonlErr != nil {
1862				content = redact.Bytes(content)
1863			} else {
1864				content = redacted.Bytes()
1865			}
1866		} else {
1867			content = redact.Bytes(content)
1868		}
1869	
1870		hash, err := CreateBlobFromContent(repo, content)
1871		if err != nil {
1872			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1873		}
1874		return hash, mode, nil
1875	}
