1877	// GetGitAuthorFromRepo retrieves the git user.name and user.email,
1878	// checking both the repository-local config and the global ~/.gitconfig.
1879	func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1880		// ConfigScoped merges local + global (local wins), matching git's own resolution.
1881		// Requires a ConfigLoader plugin to be registered; cmd/entire/main.go blank-imports
1882		// go-git/v6/x/plugin to register the default Auto loader.
1883		if cfg, err := repo.ConfigScoped(config.GlobalScope); err == nil {
1884			name = cfg.User.Name
1885			email = cfg.User.Email
1886		}
1887	
1888		// If not found in local config, try global config
1889		if name == "" || email == "" {
1890			//nolint:staticcheck // the v6 is not yet released, revisit once it is.
1891			globalCfg, err := config.LoadConfig(config.GlobalScope)
1892			if err == nil {
1893				if name == "" {
1894					name = globalCfg.User.Name
1895				}
1896				if email == "" {
1897					email = globalCfg.User.Email
1898				}
1899			}
1900		}
1901	
1902		// Provide sensible defaults if git user is not configured
1903		if name == "" {
1904			name = "Unknown"
1905		}
1906		if email == "" {
1907			email = "unknown@local"
1908		}
1909	
1910		return name, email
1911	}
