1913	// CreateCommit creates a git commit object with the given tree, parent, message, and author.
1914	// If parentHash is ZeroHash, the commit is created without a parent (orphan commit).
1915	func CreateCommit(ctx context.Context, repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
1916		now := time.Now()
1917		sig := object.Signature{
1918			Name:  authorName,
1919			Email: authorEmail,
1920			When:  now,
1921		}
1922	
1923		commit := &object.Commit{
1924			TreeHash:  treeHash,
1925			Author:    sig,
1926			Committer: sig,
1927			Message:   message,
1928		}
1929	
1930		if parentHash != plumbing.ZeroHash {
1931			commit.ParentHashes = []plumbing.Hash{parentHash}
1932		}
1933	
1934		SignCommitBestEffort(ctx, commit)
1935	
1936		obj := repo.Storer.NewEncodedObject()
1937		if err := commit.Encode(obj); err != nil {
1938			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
1939		}

