54	// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
55	// Called at stop time to finalize checkpoints with the complete session transcript.
56	//
57	// On /main: replaces prompts and compact transcript (if provided).
58	// On /full/current: replaces the raw transcript (if provided).
59	//
60	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
61	func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
62		if opts.CheckpointID.IsEmpty() {
63			return errors.New("invalid update options: checkpoint ID is required")
64		}
65	
66		sessionIndex, err := s.updateCommittedMain(ctx, opts)
67		if err != nil {
68			return fmt.Errorf("v2 /main update failed: %w", err)
69		}
70	
71		if opts.Transcript.Len() > 0 {
72			if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
73				return fmt.Errorf("v2 /full/current update failed: %w", err)
74			}
75		}
76	
77		return nil
78	}
