80	// updateCommittedMain updates prompts and compact transcript on the /main ref for an existing checkpoint.
81	// Returns the session index for coordination with /full/current.
82	func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
83		refName := plumbing.ReferenceName(paths.V2MainRefName)
84		parentHash, rootTreeHash, err := s.GetRefState(refName)
85		if err != nil {
86			return 0, ErrCheckpointNotFound
87		}
88	
89		basePath := opts.CheckpointID.Path() + "/"
90		checkpointPath := opts.CheckpointID.Path()
91	
92		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
93		if err != nil {
94			return 0, err
95		}
96	
97		rootMetadataPath := basePath + paths.MetadataFileName
98		entry, exists := entries[rootMetadataPath]
99		if !exists {
100			return 0, ErrCheckpointNotFound
101		}
102	
103		summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
104		if err != nil {
105			return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
106		}
107		if len(summary.Sessions) == 0 {
108			return 0, ErrCheckpointNotFound
109		}
110	
111		// Find session index by ID, fall back to latest
112		sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
113		if sessionIndex >= len(summary.Sessions) {
114			// findSessionIndex returns next-available when not found; fall back to latest
115			sessionIndex = len(summary.Sessions) - 1
116			logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
117				slog.String("session_id", opts.SessionID),
118				slog.String("checkpoint_id", string(opts.CheckpointID)),
119				slog.Int("fallback_index", sessionIndex),
120			)
121		}
122	
123		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
124	
125		if len(opts.Prompts) > 0 {
126			promptContent := redact.String(JoinPrompts(opts.Prompts))
127			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
128			if err != nil {
129				return 0, fmt.Errorf("failed to create prompt blob: %w", err)
130			}
131			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
132				Name: sessionPath + paths.PromptFileName,
133				Mode: filemode.Regular,
134				Hash: blobHash,
135			}
136		}
137	
138		if err := writeExtraFilesToEntries(s.repo, entries, sessionPath, opts.ExtraFiles); err != nil {
139			return 0, err
140		}
141	
142		// Replace compact transcript if provided
143		if len(opts.CompactTranscript) > 0 {
144			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
145			if err != nil {
146				return 0, fmt.Errorf("failed to create compact transcript blob: %w", err)
147			}
148			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
149				Name: sessionPath + paths.CompactTranscriptFileName,
150				Mode: filemode.Regular,
151				Hash: blobHash,
152			}
153	
154			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
155				return 0, fmt.Errorf("failed to write compact transcript hash: %w", err)
156			}
157	
158			// Keep root checkpoint summary in sync with compact artifact paths.
159			if sessionIndex >= 0 && sessionIndex < len(summary.Sessions) {
160				summary.Sessions[sessionIndex].Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
161				summary.Sessions[sessionIndex].ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
162	
163				summaryBytes, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
164				if err != nil {
165					return 0, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
166				}
167				summaryHash, err := CreateBlobFromContent(s.repo, summaryBytes)
168				if err != nil {
169					return 0, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
170				}
171				entries[rootMetadataPath] = object.TreeEntry{
172					Name: rootMetadataPath,
173					Mode: filemode.Regular,
174					Hash: summaryHash,
175				}
176			}
177		}
178	
179		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
180		if err != nil {
181			return 0, err
182		}
183	
184		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
185		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
186		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
187			return 0, err
188		}
189	
190		return sessionIndex, nil
191	}
