193	// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
194	// on /full/current while preserving other checkpoints' transcripts in the tree.
195	func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
196		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
197		if err := s.ensureRef(ctx, refName); err != nil {
198			return fmt.Errorf("failed to ensure /full/current ref: %w", err)
199		}
200	
201		parentHash, rootTreeHash, err := s.GetRefState(refName)
202		if err != nil {
203			return err
204		}
205	
206		basePath := opts.CheckpointID.Path() + "/"
207		checkpointPath := opts.CheckpointID.Path()
208		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
209	
210		// Read existing entries and replace transcript for this checkpoint only
211		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
212		if err != nil {
213			return err
214		}
215	
216		// Ignore precompute if invariants are violated — fall back to fresh chunking.
217		precomputed := opts.PrecomputedBlobs
218		if precomputed != nil && !precomputed.isUsable() {
219			precomputed = nil
220		}
221	
222		// Short-circuit: if the existing raw_transcript_hash.txt already matches
223		// the new transcript's sha256, the existing chunk entries represent the
224		// same content — preserve them and skip chunking + zlib.
225		rawTranscriptPath := sessionPath + paths.V2RawTranscriptFileName
226		rawHashPath := sessionPath + paths.V2RawTranscriptHashFileName
227		var newContentHash string
228		if precomputed != nil {
229			newContentHash = precomputed.ContentHash
230		} else {
231			newContentHash = fmt.Sprintf("sha256:%x", sha256.Sum256(opts.Transcript.Bytes()))
232		}
233		if existing, ok := entries[rawHashPath]; ok {
234			if blob, err := s.repo.BlobObject(existing.Hash); err == nil {
235				if rdr, rerr := blob.Reader(); rerr == nil {
236					existingHash, readErr := io.ReadAll(rdr)
237					_ = rdr.Close()
238					if readErr == nil && string(existingHash) == newContentHash {
239						// Content unchanged — skip tree surgery and ref advance to
240						// avoid a no-op commit on /full/current. The existing ref
241						// already references the correct tree.
242						return nil
243					}
244				}
245			}
246		}
247	
248		// Clear existing transcript artifacts for this session path before writing new ones.
249		// Preserve non-transcript metadata under the same session (e.g., tasks/*).
250		for key := range entries {
251			switch {
252			case key == rawTranscriptPath:
253				delete(entries, key)
254			case strings.HasPrefix(key, rawTranscriptPath+"."):
255				delete(entries, key)
256			case key == rawHashPath:
257				delete(entries, key)
258			}
259		}
260	
261		if err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, precomputed, sessionPath, entries); err != nil {
262			return err
263		}
264	
265		if err := s.writeContentHashFromPrecompute(newContentHash, precomputed, sessionPath, entries); err != nil {
266			return err
267		}
268	
269		// Splice into existing root tree (preserves other checkpoints' transcripts)
270		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
271		if err != nil {
272			return err
273		}
274	
275		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
276		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
277		return s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
278	}
279	
280	// writeCommittedMain writes metadata entries to the /main ref.
281	// This includes session metadata and prompts — but NOT the raw transcript
282	// (raw_transcript) or content hash (raw_transcript_hash.txt), which go to /full/current.
283	// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
284	func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
285		refName := plumbing.ReferenceName(paths.V2MainRefName)
286		if err := s.ensureRef(ctx, refName); err != nil {
287			return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
