290		parentHash, rootTreeHash, err := s.GetRefState(refName)
291		if err != nil {
292			return 0, err
293		}
294	
295		basePath := opts.CheckpointID.Path() + "/"
296		checkpointPath := opts.CheckpointID.Path()
297	
298		// Read existing entries at this checkpoint's shard path
299		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
300		if err != nil {
301			return 0, err
302		}
303	
304		// Build main session entries (metadata, prompts — no transcript or content hash)
305		sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
306		if err != nil {
307			return 0, err
308		}
309	
310		// Splice entries into root tree
311		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
312		if err != nil {
313			return 0, err
314		}
315	
316		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
317		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
318			return 0, err
319		}
