323	// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
324	// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
325	// Returns the session index used, for coordination with writeCommittedFullTranscript.
326	func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
327		// Read existing summary to get current session count
328		var existingSummary *CheckpointSummary
329		metadataPath := basePath + paths.MetadataFileName
330		if entry, exists := entries[metadataPath]; exists {
331			existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
332			if err == nil {
333				existingSummary = existing
334			}
335		}
336	
337		// Determine session index
338		sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
339	
340		// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
341		// Mirrors GitStore.writeStandardCheckpointEntries: findSessionIndex only
342		// picks slot 0 when existingSummary is nil or when the summary claims slot 0
343		// belongs to us, so the actual tree holding session-0 metadata for someone
344		// else is a corruption / stale-summary shape. Read BEFORE
345		// writeMainSessionToSubdirectory clears the subtree, or we'd only ever see
346		// our own write.
347		if sessionIndex == 0 {
348			if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
349				if existingMeta, readErr := s.gs.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
350					logging.Error(ctx, "refusing v2 checkpoint write: session 0 holds a different sessionID",
351						slog.String("checkpoint_id", opts.CheckpointID.String()),
352						slog.String("existing_session_id", existingMeta.SessionID),
353						slog.String("write_session_id", opts.SessionID),
354						slog.Bool("existing_summary_nil", existingSummary == nil))
355					return 0, fmt.Errorf(
356						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The v2 checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree %s %s/`",
357						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, paths.V2MainRefName, opts.CheckpointID.Path(),
358					)
359				}
360			}
361		}
362	
363		// Write session files (metadata and prompts — no transcript or content hash)
364		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
365		sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
366		if err != nil {
367			return 0, err
368		}
369	
370		// Build the sessions array
371		var sessions []SessionFilePaths
372		if existingSummary != nil {
373			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
374			copy(sessions, existingSummary.Sessions)
375		} else {
376			sessions = make([]SessionFilePaths, 1)
377		}
378		sessions[sessionIndex] = sessionFilePaths
379	
380		// Write root CheckpointSummary
381		if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
382			return 0, err
383		}
384		return sessionIndex, nil
385	}
386	
387	// writeMainSessionToSubdirectory writes a single session's metadata, prompts,
388	// and compact transcript to a session subdirectory (0/, 1/, 2/, … indexed by
389	// session order within the checkpoint). The raw transcript (raw_transcript) and its
390	// content hash (raw_transcript_hash.txt) go to /full/current, not here.
391	func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
392		filePaths := SessionFilePaths{}
393	
394		// Clear existing entries at this session path
395		for key := range entries {
396			if strings.HasPrefix(key, sessionPath) {
397				delete(entries, key)
398			}
399		}
400	
401		// Write prompts
402		if len(opts.Prompts) > 0 {
403			promptContent := redact.String(JoinPrompts(opts.Prompts))
404			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
405			if err != nil {
406				return filePaths, err
407			}
408			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
409				Name: sessionPath + paths.PromptFileName,
410				Mode: filemode.Regular,
411				Hash: blobHash,
412			}
413			filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
414		}
415	
416		// Write compact transcript (transcript.jsonl) + hash if provided
417		if len(opts.CompactTranscript) > 0 {
418			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
419			if err != nil {
420				return filePaths, fmt.Errorf("failed to create compact transcript blob: %w", err)
421			}
422			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
423				Name: sessionPath + paths.CompactTranscriptFileName,
424				Mode: filemode.Regular,
425				Hash: blobHash,
426			}
427			filePaths.Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
428	
429			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
430				return filePaths, fmt.Errorf("failed to write compact transcript hash: %w", err)
431			}
432			filePaths.ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
433		}
434	
435		// Write session metadata
436		sessionMetadata := CommittedMetadata{
437			CheckpointID:                opts.CheckpointID,
438			SessionID:                   opts.SessionID,
439			Strategy:                    opts.Strategy,
440			CreatedAt:                   time.Now().UTC(),
441			Branch:                      opts.Branch,
442			CheckpointsCount:            opts.CheckpointsCount,
443			FilesTouched:                opts.FilesTouched,
444			Agent:                       opts.Agent,
445			Model:                       opts.Model,
446			TurnID:                      opts.TurnID,
447			IsTask:                      opts.IsTask,
448			ToolUseID:                   opts.ToolUseID,
449			TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
450			CheckpointTranscriptStart:   opts.CompactTranscriptStart,
451			TokenUsage:                  opts.TokenUsage,
452			SessionMetrics:              opts.SessionMetrics,
453			InitialAttribution:          opts.InitialAttribution,
454			PromptAttributions:          opts.PromptAttributionsJSON,
455			Summary:                     redactSummary(opts.Summary),
456			CLIVersion:                  versioninfo.Version,
457		}
458	
459		metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
460		if err != nil {
461			return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
462		}
463		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
464		if err != nil {
465			return filePaths, err
466		}
467		entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
468			Name: sessionPath + paths.MetadataFileName,
469			Mode: filemode.Regular,
470			Hash: metadataHash,
471		}
472		filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
473	
474		return filePaths, nil
475	}
