477	// writeCompactTranscriptHash computes and writes the SHA-256 hash of the compact transcript.
478	func (s *V2GitStore) writeCompactTranscriptHash(compactTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
479		hash := fmt.Sprintf("sha256:%x", sha256.Sum256(compactTranscript))
480		blobHash, err := CreateBlobFromContent(s.repo, []byte(hash))
481		if err != nil {
482			return err
483		}
484		entries[sessionPath+paths.CompactTranscriptHashFileName] = object.TreeEntry{
485			Name: sessionPath + paths.CompactTranscriptHashFileName,
486			Mode: filemode.Regular,
487			Hash: blobHash,
488		}
489		return nil
490	}
