492	// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
493	// Transcripts accumulate across checkpoints — each write splices into the existing
494	// tree. Generation metadata (generation.json) at the tree root is updated on every
495	// write with the new checkpoint ID and timestamps.
496	//
497	// sessionIndex is the session slot (0-based), determined by the caller to stay
498	// consistent with the /main ref's session numbering.
499	// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
500	func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
501		transcript := opts.Transcript
502	
503		// TranscriptPath fallback: data read from disk is an untrusted source,
504		// so we redact it here. The in-memory path (opts.Transcript) is already
505		// pre-redacted by the caller.
506		if transcript.Len() == 0 && opts.TranscriptPath != "" {
507			rawData, readErr := os.ReadFile(opts.TranscriptPath)
508			if readErr != nil {
509				rawData = nil
510			}
511			if len(rawData) > 0 {
512				redacted, redactErr := redact.JSONLBytes(rawData)
513				if redactErr != nil {
514					return fmt.Errorf("failed to redact transcript from file: %w", redactErr)
515				}
516				transcript = redacted
517			}
518		}
519		if transcript.Len() == 0 {
520			return nil // No transcript to write
521		}
522	
523		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
524		if err := s.ensureRef(ctx, refName); err != nil {
525			return fmt.Errorf("failed to ensure /full/current ref: %w", err)
526		}
527	
528		parentHash, rootTreeHash, err := s.GetRefState(refName)
529		if err != nil {
530			return err
531		}
532	
533		basePath := opts.CheckpointID.Path() + "/"
534		checkpointPath := opts.CheckpointID.Path()
535		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
536	
537		// Read existing entries at this checkpoint's shard path
538		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
539		if err != nil {
540			return err
541		}
542	
543		// Clear existing entries at this session path before writing new ones
544		for key := range entries {
545			if strings.HasPrefix(key, sessionPath) {
546				delete(entries, key)
547			}
548		}
549	
550		if err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, nil, sessionPath, entries); err != nil {
551			return err
552		}
553	
554		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
555		if err := s.writeContentHashFromPrecompute(contentHash, nil, sessionPath, entries); err != nil {
556			return err
557		}
558	
559		// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
560		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
561		if err != nil {
562			return err
563		}
564	
565		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
566		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
567			return err
568		}
569	
570		// Check if rotation is needed after successful write.
571		// Count checkpoints by walking the tree (no generation.json on /full/current).
572		checkpointCount, countErr := s.CountCheckpointsInTree(newTreeHash)
573		if countErr != nil {
574			logging.Warn(ctx, "failed to count checkpoints for rotation check",
575				slog.String("error", countErr.Error()),
576			)
577			return nil
578		}
579		if checkpointCount >= s.maxCheckpoints() {
580			if rotErr := s.rotateGeneration(ctx); rotErr != nil {
581				logging.Warn(ctx, "generation rotation failed",
582					slog.String("error", rotErr.Error()),
583					slog.Int("checkpoint_count", checkpointCount),
584				)
585				// Non-fatal: rotation failure doesn't invalidate the write
586			}
587		}
588	
589		return nil
590	}
591	
592	// writeTranscriptBlobs writes pre-redacted, chunked transcript blobs to entries.
593	// When precomputed is non-nil, reuses its chunk blob hashes and skips both
594	// ChunkTranscript and CreateBlobFromContent.
595	func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
596		var chunkHashes []plumbing.Hash
597		if precomputed != nil {
598			chunkHashes = precomputed.ChunkHashes
599		} else {
600			chunks, err := chunkTranscript(ctx, transcript.Bytes(), agentType)
601			if err != nil {
602				return fmt.Errorf("failed to chunk transcript: %w", err)
603			}
604			chunkHashes = make([]plumbing.Hash, len(chunks))
605			for i, chunk := range chunks {
606				h, err := CreateBlobFromContent(s.repo, chunk)
607				if err != nil {
608					return err
609				}
610				chunkHashes[i] = h
611			}
612		}
613	
614		for i, blobHash := range chunkHashes {
615			chunkPath := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
616			entries[chunkPath] = object.TreeEntry{
617				Name: chunkPath,
618				Mode: filemode.Regular,
619				Hash: blobHash,
620			}
621		}
622	
623		return nil
624	}
625	
626	// writeContentHashFromPrecompute writes the content-hash blob for the given
627	// transcript hash. When precomputed is non-nil, reuses its ContentHashBlob
628	// hash; otherwise creates a fresh blob.
629	func (s *V2GitStore) writeContentHashFromPrecompute(contentHash string, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
630		var hashBlob plumbing.Hash
631		if precomputed != nil {
632			hashBlob = precomputed.ContentHashBlob
633		} else {
634			h, err := CreateBlobFromContent(s.repo, []byte(contentHash))
635			if err != nil {
636				return err
637			}
638			hashBlob = h
639		}
640		entries[sessionPath+paths.V2RawTranscriptHashFileName] = object.TreeEntry{
641			Name: sessionPath + paths.V2RawTranscriptHashFileName,
642			Mode: filemode.Regular,
643			Hash: hashBlob,
644		}
645		return nil
646	}
647	
648	// validateWriteOpts validates identifiers in WriteCommittedOptions.
649	func validateWriteOpts(opts WriteCommittedOptions) error {
650		if opts.CheckpointID.IsEmpty() {
651			return errors.New("invalid checkpoint options: checkpoint ID is required")
652		}
653		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
654			return fmt.Errorf("invalid checkpoint options: %w", err)
655		}
656		if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
657			return fmt.Errorf("invalid checkpoint options: %w", err)
658		}
659		if err := validation.ValidateAgentID(opts.AgentID); err != nil {
660			return fmt.Errorf("invalid checkpoint options: %w", err)
661		}
662		return nil
663	}
664	
665	// UpdateSummary persists an AI-generated summary into the latest session's
666	// metadata on the v2 /main ref. Mirrors GitStore.UpdateSummary for v1.
667	func (s *V2GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
668		if err := ctx.Err(); err != nil {
669			return err //nolint:wrapcheck // Propagating context cancellation
670		}
671	
672		refName := plumbing.ReferenceName(paths.V2MainRefName)
673		parentHash, rootTreeHash, err := s.GetRefState(refName)
674		if err != nil {
675			return ErrCheckpointNotFound
676		}
677	
678		basePath := checkpointID.Path() + "/"
679		checkpointPath := checkpointID.Path()
680		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
681		if err != nil {
682			return err
683		}
684	
685		rootMetadataPath := basePath + paths.MetadataFileName
686		entry, exists := entries[rootMetadataPath]
687		if !exists {
688			return ErrCheckpointNotFound
689		}
690	
691		cpSummary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
692		if err != nil {
693			return fmt.Errorf("failed to read checkpoint summary: %w", err)
694		}
695		if len(cpSummary.Sessions) == 0 {
696			return ErrCheckpointNotFound
697		}
698	
699		latestIndex := len(cpSummary.Sessions) - 1
700		sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
701		sessionEntry, exists := entries[sessionMetadataPath]
702		if !exists {
703			return fmt.Errorf("session metadata not found at index %d", latestIndex)
704		}
705	
706		metadata, err := readJSONFromBlob[CommittedMetadata](s.repo, sessionEntry.Hash)
707		if err != nil {
708			return fmt.Errorf("failed to read session metadata: %w", err)
709		}
710		metadata.Summary = redactSummary(summary)
711	
712		metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
713		if err != nil {
714			return fmt.Errorf("failed to marshal metadata: %w", err)
715		}
716		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
717		if err != nil {
718			return fmt.Errorf("failed to create metadata blob: %w", err)
719		}
720		entries[sessionMetadataPath] = object.TreeEntry{
721			Name: sessionMetadataPath,
722			Mode: filemode.Regular,
723			Hash: metadataHash,
724		}
725	
726		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, checkpointID, basePath, entries)
727		if err != nil {
728			return err
729		}
730	
731		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
732		commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, metadata.SessionID)
733		return s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
734	}
