12	// pathSafeRegex matches alphanumeric characters, underscores, and hyphens only.
13	// Used to validate IDs that will be used in file paths.
14	var pathSafeRegex = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)
15	
16	// ValidateSessionID validates that a session ID doesn't contain path separators
17	// or other unsafe characters for use in file paths.
18	// This prevents path traversal attacks when session IDs are used in file paths.
19	func ValidateSessionID(id string) error {
20		if strings.TrimSpace(id) == "" {
21			return errors.New("session ID cannot be empty")
22		}
23		if strings.ContainsAny(id, "/\\") {
24			return fmt.Errorf("invalid session ID %q: contains path separators", id)
25		}
26		return nil
27	}
28	
29	// ValidateToolUseID validates that a tool use ID contains only safe characters for paths.
30	// Tool use IDs can be UUIDs or prefixed identifiers like "toolu_xxx".
31	func ValidateToolUseID(id string) error {
32		if id == "" {
33			return nil // Empty is allowed (optional field)
34		}
35		if !pathSafeRegex.MatchString(id) {
36			return fmt.Errorf("invalid tool use ID %q: must be alphanumeric with underscores/hyphens only", id)
37		}
38		return nil
39	}
40	
41	// ValidateAgentID validates that an agent ID contains only safe characters for paths.
42	func ValidateAgentID(id string) error {
43		if id == "" {
44			return nil // Empty is allowed (optional field)
45		}
