36	
37		repo, err := git.PlainInit(repoDir, false)
38		if err != nil {
39			t.Fatalf("failed to init git repo: %v", err)
40		}
41	
42		// Configure git user for commits
43		cfg, err := repo.Config()
44		if err != nil {
45			t.Fatalf("failed to get repo config: %v", err)
46		}
47		cfg.User.Name = "Test User"
48		cfg.User.Email = "test@example.com"
49	
50		// Disable GPG signing for test commits
51		if cfg.Raw == nil {
