258	// GetLatestCheckpointIDFromHistory walks backwards from HEAD and returns
259	// the checkpoint ID from the first commit with an Entire-Checkpoint trailer.
260	// Returns an error if no checkpoint trailer is found in any commit.
261	func GetLatestCheckpointIDFromHistory(t *testing.T, repoDir string) (string, error) {
262		t.Helper()
263	
264		repo, err := git.PlainOpen(repoDir)
265		if err != nil {
266			t.Fatalf("failed to open git repo: %v", err)
267		}
268	
269		head, err := repo.Head()
270		if err != nil {
271			t.Fatalf("failed to get HEAD: %v", err)
272		}
273	
274		commitIter, err := repo.Log(&git.LogOptions{From: head.Hash()})
275		if err != nil {
276			t.Fatalf("failed to iterate commits: %v", err)
277		}
278	
279		var checkpointID string
280		//nolint:errcheck,gosec // ForEach callback returns error to stop iteration
281		commitIter.ForEach(func(c *object.Commit) error {
282			// Look for Entire-Checkpoint trailer
283			for line := range strings.SplitSeq(c.Message, "\n") {
284				line = strings.TrimSpace(line)
285				if value, found := strings.CutPrefix(line, "Entire-Checkpoint:"); found {
286					checkpointID = strings.TrimSpace(value)
287					return errors.New("stop iteration")
288				}
289			}
290			return nil
291		})
292	
293		if checkpointID == "" {
294			return "", errors.New("no commit with Entire-Checkpoint trailer found in history")
295		}
296	
297		return checkpointID, nil
298	}
