300	// SafeIDPrefix returns first 12 chars of ID or the full ID if shorter.
301	// Use this when logging checkpoint IDs to avoid index out of bounds panic.
302	func SafeIDPrefix(id string) string {
303		if len(id) >= 12 {
304			return id[:12]
305		}
306		return id
307	}
