309	// gitEmptyConfigPath returns the path to an empty file suitable for use as
310	// GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM. We use an empty file instead of
311	// os.DevNull because git on Windows cannot open NUL as a config file.
312	var gitEmptyConfig string
313	var gitEmptyConfigOnce sync.Once
314	
315	func gitEmptyConfigPath() string {
316		gitEmptyConfigOnce.Do(func() {
317			f, err := os.CreateTemp("", "git-empty-config-*")
318			if err != nil {
319				panic("create empty git config: " + err.Error())
320			}
321			_ = f.Close()
322			gitEmptyConfig = f.Name()
323		})
324		return gitEmptyConfig
325	}
326	
327	// GitIsolatedEnv returns os.Environ() with git isolation variables set.
328	// This prevents user/system git config (global gitignore, aliases, etc.) from
329	// affecting test behavior. Use this for any exec.Command that runs git or the
330	// CLI binary in integration tests.
331	//
332	// See https://git-scm.com/docs/git#Documentation/git.txt-GITCONFIGGLOBAL
333	//
334	// Existing GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM entries are filtered out before
335	// appending overrides to ensure they take effect regardless of parent env.
336	func GitIsolatedEnv() []string {
337		env := os.Environ()
338		filtered := make([]string, 0, len(env)+2)
339		for _, e := range env {
340			if strings.HasPrefix(e, "GIT_CONFIG_GLOBAL=") || strings.HasPrefix(e, "GIT_CONFIG_SYSTEM=") {
341				continue
342			}
343			filtered = append(filtered, e)
344		}
345		return append(filtered,
346			"GIT_CONFIG_GLOBAL="+gitEmptyConfigPath(), // Isolate from user's global git config (e.g. global gitignore)
347			"GIT_CONFIG_SYSTEM="+gitEmptyConfigPath(), // Isolate from system git config
348		)
349	}
