func readExtraSessionFiles(sessionTree *object.Tree) map[string][]byte {
	extras := make(map[string][]byte)
	_ = sessionTree.Files().ForEach(func(f *object.File) error { //nolint:errcheck // best-effort
		// Session-subtree files are at the root (no '/'); subtrees like tasks/ are skipped.
		if strings.Contains(f.Name, "/") {
			return nil
		}
		if standardSessionFiles[f.Name] {
			return nil
		}
		content, err := f.Contents()
		if err != nil {
			return nil //nolint:nilerr // best-effort: skip unreadable files
		}
		extras[f.Name] = []byte(content)
		return nil
	})
	if len(extras) == 0 {
		return nil
	}
	return extras
}

input.new_string:
func readExtraSessionFiles(sessionTree *object.Tree) map[string][]byte {
	extras := make(map[string][]byte)
	_ = sessionTree.Files().ForEach(func(f *object.File) error { //nolint:errcheck // best-effort
		// Session-subtree files are at the root (no '/'); subtrees like tasks/ are skipped.
		if strings.Contains(f.Name, "/") {
			return nil
		}
		if standardSessionFiles[f.Name] {
			return nil
		}
		// Use Reader, not Contents(): Contents() returns string, which loses raw
		// bytes for any non-UTF8 file. ExtraFiles is typed as []byte; mirrors the
		// shadow-branch path in extractExtraFilesFromTree.
		reader, err := f.Reader()
		if err != nil {
			return nil //nolint:nilerr // best-effort: skip unreadable files
		}
		content, err := io.ReadAll(reader)
		_ = reader.Close()
		if err != nil {
			return nil //nolint:nilerr // best-effort: skip unreadable files
		}
		extras[f.Name] = content
		return nil
	})
	if len(extras) == 0 {
		return nil
	}
	return extras
}

